const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const jointPct=n=>n===null?'—':n===0?'0%':n<.0001?`${(n*100).toExponential(2)}%`:`${(n*100).toFixed(3)}%`;
const runs=n=>n===null?'—':!Number.isFinite(n)?'∞ (impossible in model)':Number(n.toPrecision(3)).toLocaleString(undefined,{maximumFractionDigits:1});
const pct=n=>`${(n*100).toFixed(1)}%`, number=n=>Number(n||0).toLocaleString();
const labels=['Target trainee','Parent 1','Parent 2','P1 · Grandparent 1','P1 · Grandparent 2','P2 · Grandparent 1','P2 · Grandparent 2',...Array.from({length:8},(_,i)=>`Next generation ${i+1}`)];
let veteranSearch,searchUI,plannerFiltersOpen=false,goalToolsOpen=false,deckRequirementsOpen=false,supportSettingsOpen=false;
let ref,D,engine,state,route,worker,results=null,pickerIndex=0,pickerKind='veterans',detailId=null,toastTimer;
