const initial=()=>({schema:1,collections:{trainees:[],supports:[],veterans:[]},imports:{},remoteParents:[],plan:emptyPlan(),saved:[]});
const char=id=>D.characters.find(c=>c.cardId===Number(id));
const charName=id=>char(id)?.charaName??D.characters.find(c=>c.charaId===baseId(id))?.charaName??`Character ${baseId(id)}`;
const outfit=id=>char(id)?.cardTitle??`Card #${id}`;
const title=id=>`${charName(id)} ${outfit(id)}`;
const support=id=>D.supports.find(c=>c.supportCardId===Number(id));
const factor=id=>engine.factors.get(Number(id));
const sparkName=id=>factor(id)?.text??`Unknown spark ${id}`;
const skill=id=>D.skills.find(s=>s.skillId===Number(id));
const metaOptions=(items,valueFn,labelFn,selected='')=>items.map(x=>`<option value="${esc(valueFn(x))}" ${String(valueFn(x))===String(selected)?'selected':''}>${esc(labelFn(x))}</option>`).join('');
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
async function save(){try{await writeState(state);}catch(e){notify('Browser storage failed. Export a backup now to keep your changes.');}}
function invalidate(){if(results)results.stale=true;if(worker){searchGate.cancel();worker=null;searchMessage='Search cancelled because settings changed.';}save();if($('#results'))renderResults();}
function sparks(items,limit=99){return `<div class="chips">${items.slice(0,limit).map(f=>`<span class="chip type-${factor(f.id)?.type??-1}" title="${esc(sparkName(f.id))}">${esc(sparkName(f.id))} <b>${'★'.repeat(f.stars)}</b></span>`).join('')}${items.length>limit?`<span class="chip">+${items.length-limit}</span>`:''}</div>`;}
function heading(kicker,name,desc,actions=''){return `<div class="title-row"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function go(){route=location.hash.slice(1)||'planner';if(!['planner','collection','skills','data'].includes(route))route='planner';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('#breadcrumb').textContent=`WORKSPACE / ${route.toUpperCase()}`;render();}
function render({preserve=true}={}){if(!D)return;const restore=preserve?captureView($('#main')):()=>{};farmingOpen=$('#farming-controls')?.open??farmingOpen;supportSettingsOpen=$('#support-settings')?.open??supportSettingsOpen;goalToolsOpen=$('#goal-tools')?.open??goalToolsOpen;deckRequirementsOpen=$('#deck-requirements')?.open??deckRequirementsOpen;$('#main').innerHTML=({planner:renderPlanner,collection:renderCollection,skills:renderSkills,data:renderData}[route])();if(route==='collection')renderRows();if(route==='skills')renderSkillRows();if(route==='planner'&&results)renderResults();restore();if($('#search-status'))showSearchStatus(searchMessage,!!worker);}
function nodeMarkup(n,i,ev){const filled=!!n.cardId;return `<div class="node ${i===0?'target-node':''} ${filled?'':'empty-node'}"><div class="node-label">${labels[i]} ${i>0&&i<3?`<label class="check" title="Keep this imported parent during search"><input type="checkbox" data-pin="${i-1}" ${state.plan.pins[i-1]?'checked':''} aria-label="Pin parent ${i}"></label>`:''}</div><div class="avatar">${filled?ref.portrait(n.cardId):'＋'}</div><div class="node-name">${filled?esc(charName(n.cardId)):'Choose a character'}</div><div class="node-outfit">${filled?esc(outfit(n.cardId)):'From your roster or plan ahead'}</div>${sparks(n.sparks,i>2?2:3)}<div class="node-bottom">${filled?(n.remote?'uma.moe · '+esc(n.trainerId):n.sourceId?'Imported veteran':'Planned / ancestor snapshot'):'Empty slot'}${i>0&&i<7&&filled?` · ${state.plan.nodes[0].cardId?`${ev.slots[i]} affinity`:'affinity off'}`:''}</div><div class="node-tools"><button data-edit="${i}">${filled?'Edit':'Choose'}</button>${filled?`<button data-clear-node="${i}" aria-label="Clear ${labels[i]}">×</button>`:''}</div></div>`;}
function renderPlanner(){const p=state.plan,ev=p.nodes[0].cardId?engine.evaluate(p.nodes,p.parentRaceBonus):baselineEvaluation(p.nodes),odds=engine.odds(p.nodes,ev,p.rolls),white=odds.filter(o=>factor(o.id)?.type===3);const counts=state.collections;
return heading('PLAN / INHERIT / REFINE','Build your next generation.','Bring your roster together. Find the parents worth training with.',`<button data-action="new-plan">New plan</button><button data-action="export-plan">Export plan</button>`)+
`<div class="stats-row"><div class="metric"><span>VETERANS IN YOUR ROSTER</span><b>${number(counts.veterans.length)}</b><span>${counts.trainees.length} trainees · ${counts.supports.length} support cards</span></div><div class="metric"><span>LINEAGE COMPATIBILITY</span><b class="green">${p.nodes[0].cardId?ev.total:'—'} <small style="font-size:13px">${p.nodes[0].cardId?(ev.total>=151?'◎':ev.total>=51?'○':'△'):''}</small></b><span>${!p.nodes[0].cardId?'Affinity excluded · no target':ev.complete?'Complete character tree':'Provisional · incomplete tree'}</span></div><div class="metric"><span>DESIRED SPARKS</span><b>${p.wanted.length}</b><span>${p.rolls===2?'Across both inheritance events':'Per inheritance event'}</span></div></div>
${!counts.veterans.length?`<div class="notice">Start by importing your three umadump files. You can also plan characters and sparks manually. <button class="small" data-action="import">Import JSON</button></div>`:''}
<details class="panel" id="planner-filters" ${plannerFiltersOpen?'open':''}><summary>Candidate filters · Basic / Advanced / UQL</summary>${searchUI.markup('planner')}</details><div class="planner-layout"><div class="planner-main"><section class="panel"><div class="panel-head"><h2>Lineage workspace</h2><span class="badge">${p.parentRaceBonus?'PARENT–PARENT G1 ON':'GLOBAL · PARENT–PARENT G1 OFF'}</span></div><p class="tiny" data-help-note="this setting">Choose the target, then two veterans. Their parents fill the grandparent slots automatically.</p><div class="tree"><div class="tree-row target">${nodeMarkup(p.nodes[0],0,ev)}</div><div class="tree-row parents">${p.nodes.slice(1,3).map((n,i)=>nodeMarkup(n,i+1,ev)).join('')}</div><div class="tree-row grandparents">${p.nodes.slice(3,7).map((n,i)=>nodeMarkup(n,i+3,ev)).join('')}</div></div><details><summary>Plan the next generation · 8 additional slots</summary><p class="tiny">These slots help plan future grandparents. They do not contribute directly to this target’s inheritance odds.</p><div class="generation3">${p.nodes.slice(7).map((n,i)=>nodeMarkup(n,i+7,ev)).join('')}</div></details>${ev.issues.length?`<div class="notice warning">${ev.issues.map(esc).join('<br>')}</div>`:''}<details><summary>Compatibility breakdown & calculation rules</summary><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Direct</th><th>Three-way</th><th>G1 bonus</th></tr></thead><tbody>${ev.branches.map((b,i)=>`<tr><td>Parent ${i+1}</td><td>${b.direct}</td><td>${b.triples}</td><td>${b.race}</td></tr>`).join('')}<tr><td>Parent pair</td><td>${ev.pair}</td><td>—</td><td>${ev.pairRace}</td></tr></tbody></table></div><p class="tiny">Shared G1 groups count once per relationship, at +3 each. Each parent’s spark odds use its branch plus the parent-pair relation. Each grandparent uses its three-way relation plus its shared G1 bonus with its parent. Missing race histories can understate these values.</p><label class="check"><input type="checkbox" id="parent-race" ${p.parentRaceBonus?'checked':''}> Include parent-to-parent shared-G1 bonus (alternate / JP-style rule)</label><p class="tiny">The bundled catalog is Global. This switch changes one rule; it does not provide a complete JP data mode. Community calculations are estimates, not guaranteed game outcomes.</p></details></section>
<section id="results" class="search-results" aria-live="polite"></section><section class="panel"><div class="panel-head"><h2>Inheritance odds</h2><label><select id="rolls" aria-label="Inheritance period"><option value="2" ${p.rolls===2?'selected':''}>Both events</option><option value="1" ${p.rolls===1?'selected':''}>One event</option></select></label></div><p class="tiny" data-help-note="this setting">Chance of receiving each spark at least once. Starting inheritance is excluded; sources roll independently.</p>${!ev.complete?'<div class="notice warning">Complete a valid seven-character tree to display percentages.</div>':odds.length?`<div class="table-wrap"><table><thead><tr><th>Spark</th><th>Copies / stars</th><th>At least once</th><th>At least twice</th></tr></thead><tbody>${odds.map(o=>`<tr><td>${esc(sparkName(o.id))}<span class="row-sub">${categories[factor(o.id)?.type]??'Unknown'}</span></td><td>${o.copies} / ${o.stars}★</td><td class="percent">${pct(o.chance)}<div class="bar"><span style="width:${o.chance*100}%"></span></div></td><td>${pct(Math.max(0,o.twice))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Add parent or grandparent sparks to see their odds.</p>'}<details><summary>White-spark creation after training</summary><p class="tiny" data-help-note="this setting">A separate model: chance to generate a white skill spark after finishing a career, conditional on learning the corresponding skill. Each lineage copy multiplies the base chance by 1.1. This does not predict star level or skill availability.</p>${white.length?`<div class="table-wrap"><table><thead><tr><th>Skill spark</th><th>Copies</th><th>Learned ○</th><th>Learned ◎</th><th>Learned gold</th></tr></thead><tbody>${white.map(o=>`<tr><td>${esc(sparkName(o.id))}</td><td>${o.copies}</td><td>${pct(creationChance(o.copies))}</td><td>${pct(creationChance(o.copies,'upgraded'))}</td><td>${pct(creationChance(o.copies,'gold'))}</td></tr>`).join('')}</tbody></table></div>`:'<p>No white skill sparks selected.</p>'}</details></section></div>
<aside class="panel side-panel" ><div class="eyebrow">SEARCH YOUR ROSTER</div><h2>Find my parents</h2>${planningControls()}${farmingControls()}<p data-help-note="ranking">${p.farmingObjective&&p.farmingObjective!=='legacy'?objectiveHelp[p.farmingObjective]:p.includeSupports?'Rank parent-and-deck matches by the selected skill / training-value balance.':'Rank eligible pairs by the lowest desired-spark chance, then combined chances, then compatibility.'}</p><hr>${remotePoolMarkup()}<label class="check"><input id="include-supports" type="checkbox" ${p.includeSupports?'checked':''}> Include support cards</label>${p.includeSupports?`<details id="support-settings" ${supportSettingsOpen?'open':''}><summary>Support deck · automatic / manual</summary><div class="notice"><b>Five owned + one borrowed support</b><p class="tiny">Searches skill coverage for end-of-career spark creation. Hints, events and awakening skills are potential sources, not guaranteed unlocks. Veterans contribute their recorded sparks; learned skills alone cannot be inherited. Deck search is approximate; training value uses the Euophrys expectation model.</p><label class="check"><input id="borrow-ssr" type="checkbox" ${p.borrowSSR!==false?'checked':''}> Borrow SSR only (assume MLB / max level)</label>${manualDeckControls()}${trainingControls()}<p class="tiny" data-help-note="this setting">Uncheck SSR only to allow any rarity. Cards sharing a character, or matching the target, cannot be used together. Without a target, recheck deck legality when choosing one.</p></div></details>`:''}<div class="filter-grid"><div><label>Desired spark<input id="wanted-search" list="factor-list" placeholder="Type a name or ID…"></label><datalist id="factor-list">${[...engine.factors].map(([id,f])=>`<option value="${esc(f.text)} (#${id})"></option>`).join('')}</datalist><button class="small" data-action="add-wanted">＋ Add spark</button><div>${p.wanted.map(id=>`<div class="wanted"><span>${esc(sparkName(id))}</span>${priorityMarkup(id)}<button data-remove-wanted="${id}" aria-label="Remove ${esc(sparkName(id))}">×</button></div>`).join('')}</div></div><div><label>Search outcome<select id="search-mode" ${p.includeSupports?'disabled':''}><option value="inherit" ${p.searchMode!=='sparkgen'&&!p.includeSupports?'selected':''}>Inspiration · inherit sparks</option><option value="sparkgen" ${p.searchMode==='sparkgen'||p.includeSupports?'selected':''}>Spark % · after this career</option></select></label>${boughtMarkup()}${p.deck?.length?`<details><summary>Applied support deck</summary><p class="tiny">Saved deck snapshot. Rerun the search after changing target, skills, or scenario settings.</p>${deckMarkup(p.deck,[],p.training)}</details>`:''}<p class="inline-note" data-help-note="search assumptions">Pin either imported parent to search around it. ${p.includeSupports?'Without a target, affinity and race bonuses are excluded and growth is neutral; support sources still count. With no desired sparks, decks rank by training value.':'Without a target, all affinity and race bonuses are excluded; only recorded sparks count. With no desired sparks, only affinity ranks pairs; without a target those pairs tie.'} With a target, complete ancestry and known compatibility are required.</p></div></div><button class="primary" data-action="find-parents" ${!counts.veterans.length?'disabled':''}>${p.includeSupports?'Find parents & deck':'Find parent pairs'} →</button><div id="search-status" role="status"></div><hr><h3>Save this plan</h3><div class="save-row"><input id="plan-name" aria-label="Plan name" value="${esc(p.name)}"></div><button class="full" data-action="save-plan">Save snapshot</button><div>${state.saved.map((s,i)=>`<div class="saved-plan"><button class="small" data-load-plan="${i}">${esc(s.name)}</button><button class="small danger" data-delete-plan="${i}" aria-label="Delete ${esc(s.name)}">×</button></div>`).join('')}</div></aside></div>`;}
const objectiveHelp={
 legacy:'Preserves the existing ranking. Without supports: weakest chance first, then total chances, then affinity. With supports: equal blend of weakest and average chance, mixed with the training-value weight. Spark priorities do not affect this mode.',
 balanced:'Protects the weakest requested chance while improving overall coverage. Score = ½ × weakest chance + ½ × weighted average chance. Example: 40%, 40%, 40% scores 40/100. This is a preference score, not a probability of success.',
 yield:'Maximizes weighted expected distinct sparks: sum(priority × chance). Displayed expected sparks = sum(chance), without weights. Example: 80%, 40%, 10% yields 1.30 requested sparks per run on average. Independence is not required. For blending with training, divide weighted yield by total priority weight.',
 package:'Maximizes the estimated chance of every requested outcome together: multiply distinct chances. Example: 40% × 40% × 40% = 6.4%; average runs ≈ 1 / 0.064 = 15.6. Assumes independent outcomes and identical repeat attempts. Priorities are ignored because every outcome is required. Not a guarantee.'
};
function farmingControls(){const p=state.plan,mode=p.farmingObjective??'legacy';return `<details class="farming-controls" id="farming-controls" ${farmingOpen?'open':''}><summary>Farming objectives & presets ${info('farming objectives','Choose what makes a useful result. Current ranking preserves existing behavior. These settings rank candidates; they never change game probabilities.')}</summary><label>Objective ${info(objectives[mode],objectiveHelp[mode])}<select id="farming-objective" aria-label="Farming objective">${metaOptions(Object.entries(objectives),x=>x[0],x=>x[1],mode)}</select></label><details><summary>Calculation details</summary><p class="tiny">${esc(objectiveHelp[mode])}</p><p class="tiny">Probabilities use the selected search outcome: inheritance, or end-of-career white-spark creation. Other spark types remain inheritance outcomes. Mixed lists therefore describe mixed events, not a complete generated veteran. Interchangeable normal/+ forms count once, using the lower chance and highest priority if their assumptions differ.</p><p class="tiny">With supports: score = 100 × [(1 − training weight) × objective utility + training weight × training index / (training index + 3000)]. Balanced utility is the balanced score; yield utility is weighted average; package utility is its joint probability. The displayed score is a preference index. No desired sparks means only training value contributes (or affinity without supports).</p></details><button class="small" data-action="reset-farming">Reset objective & priorities</button><hr><label>Farming preset name<input id="farming-name" maxlength="100" placeholder="e.g. Groundwork loop"></label><div class="actions"><button class="small" data-action="save-farming">Save preset</button><button class="small" data-action="export-farming">Export current</button><button class="small" data-action="import-farming">Import</button></div><input id="farming-import" type="file" accept="application/json,.json" hidden><label>Saved farming presets<select id="farming-preset"><option value="">Choose…</option>${(state.farmingPresets??[]).map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select></label><div class="actions"><button class="small" data-action="load-farming">Load preset</button><button class="small" data-action="delete-farming">Delete preset</button>${info('farming presets','Saves desired sparks, priorities, objective, learning assumptions, scenario, support constraints, outcome, inheritance rules, sorting and candidate filters. Loading preserves your target, lineage and pinned parents; clears the applied deck and marks results outdated. Collection data is never included. Workspace backups include these presets.')}</div></details>`;}
function priorityMarkup(id){const mode=state.plan.farmingObjective??'legacy',off=mode==='legacy'||mode==='package',w=priority(state.plan,id);return `<span class="priority-control"><select data-priority-level="${id}" aria-label="Priority for ${esc(sparkName(id))}" ${off?'disabled':''}>${metaOptions([[.5,'Low'],[1,'Normal'],[3,'High'],...(![.5,1,3].includes(w)?[[w,'Custom']]:[])],x=>x[0],x=>x[1],w)}</select><input type="number" min="0.1" max="100" step="0.1" data-spark-weight="${id}" value="${w}" aria-label="Numeric priority for ${esc(sparkName(id))}" ${off?'disabled':''}>${info('spark priority',off?'Priorities are retained but ignored by Current ranking and Complete package. Choose Balanced coverage or Most desired sparks to use them.':'Relative importance: Low 0.5, Normal 1, High 3, or a custom positive weight up to 100. Higher weight changes ranking, not probability. Balanced still protects the weakest spark regardless of weight.')}</span>`;}
function checkedFarmingPreset(p){
 if(!p||p.version!==1||typeof p.name!=='string'||!p.settings||Array.isArray(p.settings))throw Error('Invalid farming preset.');
 const candidate=validatePlan(restoreFarmingSettings(emptyPlan(),p,emptyPlan()));
 for(const key of ['includeSupports','borrowSSR','parentRaceBonus','countEventSources','scenarioHints','recoveryAdjustment'])if(candidate[key]!==undefined&&typeof candidate[key]!=='boolean')throw Error('Invalid preset switch.');
 if(candidate.deckMinimums&&(typeof candidate.deckMinimums!=='object'||Object.values(candidate.deckMinimums).some(n=>!Number.isInteger(n)||n<0||n>6)))throw Error('Invalid deck minimums.');
 if(candidate.minRaceBonus!==undefined&&(!Number.isFinite(candidate.minRaceBonus)||candidate.minRaceBonus<0||candidate.minRaceBonus>100))throw Error('Invalid race bonus.');
 if(candidate.wanted.length>200)throw Error('Maximum 200 desired sparks.');
 return captureFarmingPreset(candidate,cleanSearch(p.search),p.name);
}
function saveFarmingPreset(){const name=$('#farming-name').value.trim();if(!name)return notify('Enter a farming preset name.');state.farmingPresets??=[];if(state.farmingPresets.length>=100)return notify('Maximum 100 farming presets.');state.farmingPresets.push(checkedFarmingPreset(captureFarmingPreset(state.plan,state.searches.planner,name)));save();render();notify('Saved farming settings and candidate filters.');}
function loadFarmingPreset(){const p=state.farmingPresets?.[Number($('#farming-preset').value)];if($('#farming-preset').value===''||!p)return notify('Choose a farming preset.');const preset=checkedFarmingPreset(p);state.plan=validatePlan(restoreFarmingSettings(state.plan,preset,emptyPlan()));state.searches.planner=cleanSearch(preset.search);invalidate();render();notify('Loaded farming preset; target and lineage retained.');}
async function importFarmingPreset(file){try{if(file.size>1024*1024)throw Error('Preset exceeds 1 MB.');const data=JSON.parse(await file.text());if(data.format!=='umaplan-farming')throw Error('Not a farming preset file.');const preset=checkedFarmingPreset(data.preset);state.farmingPresets??=[];if(state.farmingPresets.length>=100)throw Error('Maximum 100 farming presets.');state.farmingPresets.push(preset);save();render();notify('Imported preset. Select it and Load to apply.');}catch(e){notify('Preset import failed: '+e.message);}}
function comparisonControls(){return `<p class="tiny">Objective: <b>${esc(objectives[results.plan?.farmingObjective??'legacy'])}</b> · Select Compare on two matches to inspect their differences. ${info('result comparisons','Both matches come from the same search snapshot. Changing settings marks that snapshot outdated; percentages and explanations retain the settings used to calculate them.')}</p>`;}
function matchLabel(r){const rows=results.veterans??state.collections.veterans;return [r.a,r.b].map(id=>{const v=rows.find(v=>v.id===id);return `${v?charName(v.cardId):'Veteran'} #${id}`;}).join(' + ');}
function sourceDescription(r,i,p){const a=r.acquisition?.[i],id=p.wanted[i];if(a){if(a.kind==='inspiration')return `Inspiration required (${pct(a.chance)})`;if(a.kind==='inheritance')return 'Inheritance only';return `${a.skillName??sparkName(id)} · ${a.kind==='scenario'?'Scenario hint':a.kind.startsWith('support')?(support(a.entityId)?.charaName??a.entityId):charName(a.entityId)} · ${a.detail??a.kind}${a.borrowed?' · borrowed':''}${a.learnedTier?' · learned '+a.learnedTier:''} · conditional source`;}
 if(p.searchMode!=='sparkgen'||factor(id)?.type!==3)return 'Recorded ancestor spark · inheritance';const b=p.bought?.[id]??{};return b.inspirationOnly?'Inspiration required · normal skill':`Assumed learned ${b.tier??'white'} skill`;}
function explainMatch(index){const r=results.top[index],p=results.plan,f=r.farming;const rows=results.veterans;const nodes=pairNodes(p.nodes[0],rows.find(v=>v.id===r.a),rows.find(v=>v.id===r.b));const ev=p.nodes[0].cardId?engine.evaluate(nodes,p.parentRaceBonus):baselineEvaluation(nodes);const odds=new Map(engine.odds(nodes,ev,p.rolls).map(o=>[o.id,o]));
 openModal(modalHeader('Why this match?')+`<p>${esc(matchLabel(r))}</p>${results.stale?'<div class="notice warning">Outdated results: explanation uses the original search settings.</div>':''}<p><b>${esc(objectives[f.objective])}</b> · ${esc(objectiveHelp[f.objective])}</p><p>Expected distinct outcomes: ${f.expectedYield?.toFixed(3)??'—'} · Weighted yield: ${f.weightedYield?.toFixed(3)??'—'} priority points · Balanced score: ${f.balanced==null?'—':(100*f.balanced).toFixed(2)} / 100.</p><p>All outcomes together ≈ ${jointPct(r.allChance)} · Average attempts ≈ ${runs(r.expectedRuns)}. Independence assumed. ${p.searchMode==='inherit'&&!p.includeSupports?'These are inheritance outcomes.':'White skill chances are creation estimates; other types are inheritance outcomes.'}</p><div class="table-wrap"><table><thead><tr><th>Distinct outcome</th><th>Chance</th><th>Priority</th><th>Weighted yield contribution</th><th>Lineage copies</th><th>Acquisition</th></tr></thead><tbody>${f.groups.map(g=>`<tr><td>${g.ids.map(id=>esc(sparkName(id))).join(' / ')}</td><td>${pct(g.p)}</td><td>${g.weight}${['legacy','package'].includes(f.objective)?' (not used)':''}</td><td>${(g.p*g.weight).toFixed(3)}</td><td>${g.ids.map(id=>odds.get(id)?.copies??0).join(' / ')}</td><td>${g.ids.map(id=>esc(sourceDescription(r,p.wanted.indexOf(id),p))).join('<br>')}</td></tr>`).join('')}</tbody></table></div><p>${f.objective==='legacy'&&!r.training?'Ranking: weakest chance → total chances → affinity.':`Score contributions: skills ${f.skillPoints.toFixed(3)} + training ${f.trainingPoints.toFixed(3)} = ${(f.skillPoints+f.trainingPoints).toFixed(3)} points. Training weight ${(100*f.trainingWeight).toFixed(0)}%.`} Affinity ${r.baseline?'excluded (no target)':r.total}; already reflected in inheritance probabilities.</p><p class="tiny">Weighted contribution explains yield. Balanced additionally includes the weakest chance; Complete package multiplies chances and cannot be split into additive per-skill points. Aliases count once, using the lower probability and highest weight. Source access is conditional: hint RNG, event completion and skill-point budgets are not simulated.</p>${r.training?trainingMarkup(r.training,r.combinedScore):''}`);
}
function compareMatches(){const [a,b]=compared.map(i=>results.top[i]),p=results.plan;const fmt=n=>n==null?'—':!Number.isFinite(n)?'∞':n.toFixed(3);const row=(label,x,y,percent=false)=>`<tr><th>${esc(label)}</th><td>${x==null?'—':percent==='joint'?jointPct(x):percent?pct(x):fmt(x)}</td><td>${y==null?'—':percent==='joint'?jointPct(y):percent?pct(y):fmt(y)}</td><td>${x==null||y==null||!Number.isFinite(x)||!Number.isFinite(y)?'—':`${y-x>=0?'+':''}${((y-x)*(percent?100:1)).toFixed(3)}${percent?' pp':''}`}</td></tr>`;
 openModal(modalHeader('Compare parent matches')+`${results.stale?'<div class="notice warning">Outdated search snapshot. Rerun before applying either match.</div>':''}<p>Right minus left. Higher chances and yield are better; fewer estimated runs are better. Ranking scores reflect your selected preferences.</p><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Measure</th><th>${esc(matchLabel(a))}</th><th>${esc(matchLabel(b))}</th><th>Difference</th></tr></thead><tbody>${row('Ranking score',a.combinedScore,b.combinedScore)}${row('Expected distinct outcomes',a.farming.expectedYield,b.farming.expectedYield)}${row('Weighted yield',a.farming.weightedYield,b.farming.weightedYield)}${row('Balanced score / 100',a.farming.balanced==null?null:a.farming.balanced*100,b.farming.balanced==null?null:b.farming.balanced*100)}${row('All together ≈',a.allChance,b.allChance,'joint')}${row('Average runs ≈',a.expectedRuns,b.expectedRuns)}${row('Affinity',a.baseline?null:a.total,b.baseline?null:b.total)}${row('Training index',a.training?.score,b.training?.score)}${p.wanted.map((id,i)=>row(sparkName(id),a.chances[i],b.chances[i],true)).join('')}<tr><th>Scenario</th><td>${esc(scenarioNames[a.training?.scenario]??'—')}</td><td>${esc(scenarioNames[b.training?.scenario]??'—')}</td><td>—</td></tr><tr><th>Cards</th>${[a,b].map(r=>`<td>${(r.deck??[]).map(c=>`${esc(support(c.id)?.charaName??c.id)} #${c.id}${c.borrowed?' (borrowed)':''}`).join('<br>')||'No deck'}</td>`).join('')}<td>—</td></tr></tbody></table></div><p class="tiny">Package probabilities assume independent outcomes; mixed lists combine creation and inheritance events. Priority changes do not change these probabilities.</p>`);
}

function planningControls(){const p=state.plan,preset=goalPresets.find(x=>x.id===p.goalPreset),course=D.courses.courses.find(c=>c.course_id===p.courseId),summary=course?courseSummary(course):null;return `<details id="goal-tools" ${goalToolsOpen?'open':''}><summary>Parent goal presets & course context</summary><p class="tiny" data-help-note="this setting">Add a starting skill package for a parent-farming run. Presets retain your target, lineage, filters and existing sparks; a backup plan is saved before applying. The 90% skills / 10% training balance is Umaplan's editable starting preference.</p><label>Parent goal<select id="goal-preset">${goalPresets.map(x=>`<option value="${x.id}" ${x.id===p.goalPreset?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="small" data-action="apply-goal">Apply goal preset</button>${preset?`<p class="tiny">${esc(preset.note)} <a href="${preset.source}" target="_blank" rel="noopener">Guide</a></p>`:''}<p class="tiny">Aim for SS (17,500 rating) when making final parents and 1,100 in desired blue-spark stats. Training index does not predict whether those targets will be reached. Gold skills help generate white sparks; their race value is a separate question.</p><label>Course context<select id="course-context"><option value="">No course selected</option>${D.courses.courses.map(c=>`<option value="${c.course_id}" ${c.course_id===p.courseId?'selected':''}>${esc(c.trackName)} · ${c.distance}m ${c.surface===1?'Turf':'Dirt'} · #${c.course_id}</option>`).join('')}</select></label>${course?`<p class="tiny">${esc(course.trackName)} · ${course.distance}m · ${course.turn===1?'Right':course.turn===2?'Left':'Straight'}<br>Late-race begins at ${summary.lateStart.toFixed(1)}m. Final straight: ${summary.finalStraight==null?'unavailable':summary.finalStraight+'m → '+course.distance+'m'}. ${summary.finalStraight==null?'':summary.finalStraight<summary.lateStart?'Final straight begins before late-race; check speed carryover timing.':'Final straight begins at or after late-race; check acceleration timing.'}</p>`:''}<p class="tiny">Course context is informational; it does not change spark odds or simulate skill effectiveness. <a href="https://uma.moe/competitive/race-analysis" target="_blank" rel="noopener">Race analysis</a> · <a href="https://uma.moe/competitive/cm-data" target="_blank" rel="noopener">CM observations</a> · <a href="https://uma.moe/research" target="_blank" rel="noopener">Research</a></p></details>`;}
function deckConstraintControls(){const p=state.plan;return `<details id="deck-requirements" ${deckRequirementsOpen?'open':''}><summary>Deck templates & requirements</summary><label>Scenario template<select id="deck-template">${p.deckTemplate==='custom'?'<option value="custom" selected>Custom requirements</option>':''}${Object.entries(deckTemplates).map(([id,t])=>`<option value="${id}" ${(p.deckTemplate??'free')===id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><button class="small" data-action="apply-deck-template">Apply deck template</button><p class="tiny" data-help-note="this setting">Templates set scenario, card-type minimums and race bonus. Remaining slots are flexible. They do not force a named card; consider Riko for Unity and Light Hello for Grand Concert. Adjust around growth, inherited stats, skills and stamina needs.</p><div class="filter-grid">${deckTypes.map(t=>`<label>Minimum ${t==='Intelligence'?'Wit':t}<input type="number" min="0" max="6" step="1" data-deck-minimum="${t}" value="${p.deckMinimums?.[t]??0}"></label>`).join('')}<label>Minimum race bonus %<input id="min-race-bonus" type="number" min="0" max="100" value="${p.minRaceBonus??0}"></label></div><p class="tiny" data-help-note="this setting">Requirements include the borrowed slot. Race bonus assumes max level at each owned card's current limit break. The bounded search can miss valid decks. <a href="https://uma.guide/guides/unity-cup-deckbuilding-guide" target="_blank" rel="noopener">Unity</a> · <a href="https://uma.guide/guides/trackblazer" target="_blank" rel="noopener">Trackblazer</a> · <a href="https://uma.guide/guides/grand-concert" target="_blank" rel="noopener">Grand Concert</a></p><label class="check"><input id="count-event-sources" type="checkbox" ${p.countEventSources!==false?'checked':''}> Count potential card / character event skills</label><p class="tiny" data-help-note="this setting">For conservative Independent Training plans, turn this off: event-chain completion rates are not modeled. Innate skills and training hints still count. Character event skills are excluded in Trackblazer.</p><label class="check"><input id="scenario-hints" type="checkbox" ${p.scenarioHints!==false?'checked':''}> Count Racing Spirit / Ignited Spirit scenario hints</label><p class="tiny">Conditional on earning and buying the hint in URA / Unity. Uses the normal white tier; other scenario rewards and gold upgrades are not assumed. “Inspiration only” overrides these sources. Normal/+ sparks remain a shared family estimate, not separately validated variant odds.</p></details>`;}

function trainingControls(){const p=state.plan,g=char(p.nodes[0].cardId);return `<div class="training-controls">${deckConstraintControls()}<label>Maximum Pal / Group cards<select id="max-outing-cards">${metaOptions([0,1,2,3,4,5,6],x=>x,x=>x===1?'1 · recommended default':String(x),p.maxOutingCards??1)}</select></label><p class="tiny" data-help-note="this setting">Planning preference, not a game restriction. Outing turns are shared across the deck; stacking Pal/Group cards leaves fewer training turns.</p><label>Training scenario<select id="training-scenario">${metaOptions([['auto','Automatic · best modeled value'],...Object.entries(scenarioNames)],x=>x[0],x=>x[1],p.scenario??'auto')}</select></label><details><summary>Scenarios to compare automatically</summary>${Object.entries(scenarioNames).map(([id,name])=>`<label class="check"><input type="checkbox" data-auto-scenario="${id}" ${(p.autoScenarios??['URA','Aoharu','MANT','GL']).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}<p class="tiny" data-help-note="this setting">Enable only scenarios available to you. Grand Masters is opt-in. Automatic compares these presets; a manual choice overrides this list.</p></details><label class="check"><input id="recovery-adjustment" type="checkbox" ${p.recoveryAdjustment!==false?'checked':''}> Reduce recovery value in Wit-heavy decks</label><p class="tiny" data-help-note="this setting">Planning estimate: energy value is divided by 1 + half the number of Wit cards. This approximates lower recovery demand; it does not simulate the energy cap. Turn off to use the original energy valuation.</p><label>Training focus ${info('training focus','Changes which stat the expectation model values most. Balanced values all stats and skill points; target growth rates are applied separately. This is a relative deck index, not predicted final stats.')}<select id="training-focus" aria-label="Training focus">${metaOptions(['balanced','speed','stamina','power','guts','wisdom'],x=>x,x=>x==='wisdom'?'Wit':x,p.trainingFocus??'balanced')}</select></label><label>Training-value weight ${info('training-value weight','Mixes objective utility with training index / (index + 3000). 0% ranks only desired outcomes; 100% ranks only training value. In Complete package mode, small joint probabilities can make training dominate: use 0% for a strict package search.')}<select id="training-weight" aria-label="Training-value weight">${metaOptions([0,10,25,50,75,100],x=>x,x=>`${x}% training / ${100-x}% skills`,p.trainingWeight??25)}</select></label><p class="tiny">Growth: ${g?['Speed','Stamina','Power','Guts','Wisdom'].map(k=>`${k} +${g['talent'+k]??0}%`).join(' · '):'no target → neutral (0%)'}. Owned cards are modeled at their current limit-break cap, assuming you level them; the displayed level is your imported level. Borrowed cards are MLB at max level. Training value is a relative index, not predicted final stats.</p></div>`;}
function trainingMarkup(t,score){return `<div class="training-summary"><b>${esc(scenarioNames[t.scenario]??'Training model unavailable')}</b>${score!=null?` · combined score ${score.toFixed(1)}`:''}<span class="row-sub">Training index ${number(Math.round(t.score))} · Race bonus ${t.raceBonus==null?'unknown':t.raceBonus+'%'}${t.neutralGrowth?' · neutral growth':''}</span><details><summary>Scenario comparison & card contributions</summary>${t.comparisons.map(c=>`<p class="tiny">${esc(scenarioNames[c.scenario])}: ${number(Math.round(c.score))}</p>`).join('')}${(t.perCard??[]).map(c=>`<p class="tiny">${esc(support(c.id)?.charaName??c.id)}: ${number(Math.round(c.score))}${c.scenarioLinked?' · scenario-linked':''}${c.scenarioBonus?' · link index +'+c.scenarioBonus:''}</p>`).join('')}${t.missing.length?`<p class="tiny">No model for cards: ${t.missing.map(esc).join(', ')}</p>`:''}<p class="tiny">Recovery / energy-saving value: ${Math.round((t.energyUtilization??1)*100)}% of raw model value. Reduced with Wit-card count to approximate lower energy demand; not a turn-by-turn simulation. Scenario bonuses are coarse index allowances, not predicted stats or performance tokens. Riko’s ordinary outings remain available outside Unity; Light Hello’s performance-point benefit is only represented in Grand Concert’s link allowance.</p><p class="tiny">Shared outing allowance: ${t.outingDays??'not recorded'} turns. Sum of each card’s marginal score with the other five fixed; not a full-career simulation. Common stat weights allow scenario comparison. Best found in a bounded search, not a guaranteed global optimum.</p></details></div>`;}
function deckMarkup(cards,acquisition=[],training=null,combined=null,wanted=state.plan.wanted){return `${training?trainingMarkup(training,combined):''}`+`<div class="match-deck">${cards.map(c=>{const meta=support(c.id);return `<div class="deck-card">${ref.supportArt(c.id)}<span>${esc(meta?.charaName??c.id)}<br><b>${c.borrowed?'Borrowed · MLB':'Owned · '+c.limitBreak+'/4 LB'}</b><br>${esc(meta?.rarityDisplay??'')} · Lv ${c.level??'?'} · ${esc(meta?.supportCardTypeName??'')}</span></div>`;}).join('')}</div>${acquisition.length?`<details><summary>Skill sources & assumptions</summary>${acquisition.map((a,i)=>`<p class="tiny"><b>${esc(sparkName(wanted[i]))}</b>: ${a.kind==='inspiration'?`Inspiration required (${pct(a.chance)})`:a.kind==='inheritance'?'Inheritance only':`${esc(a.skillName)} · ${a.kind==='scenario'?'Scenario hint':a.kind.startsWith('support')?esc(support(a.entityId)?.charaName??a.entityId):esc(charName(a.entityId))} · ${esc(a.detail)}${a.borrowed?' · borrowed':''}${a.learnedTier?' · learned '+esc(a.learnedTier):''} (conditional)`}</p>`).join('')}<p class="tiny">Source access does not model hint RNG, event completion, skill-point cost, or awakening unlocks. Confirm those before training. Source tier follows Automatic or your selected tier cap. Inspiration only bypasses deck access.</p></details>`:''}`;}
function matchSortControls(){const p=state.plan,options=[['recommended','Recommended'],['average','Average chance'],['allChance','All in one run'],['expectedRuns','Estimated runs'],['min','Lowest spark chance'],['affinity','Affinity'],...(p.includeSupports?[['training','Deck training value']]:[]),...p.wanted.map((id,i)=>['spark:'+i,sparkName(id)])];return `<div class="filter-grid"><label>Sort parent matches<select id="match-sort">${options.map(([value,label])=>`<option value="${value}" ${(p.matchSort??'recommended')===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Order<select id="match-direction" ${!p.matchSort||p.matchSort==='recommended'?'disabled':''}><option value="desc" ${p.matchDirection!=='asc'?'selected':''}>Highest first</option><option value="asc" ${p.matchDirection==='asc'?'selected':''}>Lowest first</option></select></label></div><p class="tiny" data-help-note="this setting">Changing sort searches all eligible pairs again to select the best 40 for that order. Deck selection keeps your skill / training-value balance.</p>`;}
function renderResults(){const el=$('#results');if(!el||!results)return;const p=results.plan??state.plan,restore=captureView(el);el.innerHTML=`<div class="panel"><div class="panel-head"><h2>${p.includeSupports?'Parent matches & deck':'Parent matches'}</h2><span class="badge">${number(results.matched)} eligible pairs</span></div>${results.stale?'<div class="notice warning stale-results">These results are outdated. Settings or collection data changed. Run the search again before applying a pair.</div>':''}${comparisonControls()}${matchSortControls()}<details><summary>How to read these estimates</summary><p class="tiny">${p.includeSupports?'Skill columns show end-of-career creation chances, conditional on learning the listed support or character skill. Deck search balances skill coverage with a relative training-value model; hint/event success remains unmodeled. ':''}${p.searchMode==='sparkgen'||p.includeSupports?'Skill columns show end-of-career spark chances; other spark types show inheritance odds.':'Columns show inheritance odds.'} ${!p.nodes[0].cardId?'Affinity-free baseline; not target-specific career odds.':''} Average chance is the arithmetic mean of the requested chances. All-in-one-run odds multiply distinct outcomes, assuming independence; interchangeable forms count once. Average runs = 1 ÷ all-in-one-run probability, assuming identical independent attempts. This is an estimate, not a guarantee; one-event mode covers only that event. With no desired sparks, summaries are unavailable. Best ${results.top.length} shown. Search uses imported veterans and any enabled remote snapshots (maximum one borrowed parent per pair); manually edited grandparent slots are replaced when a pair is applied.</p></details>${!results.top.length?'<div class="empty"><h2>No matching pair</h2><p>Remove a pin or import more veterans. With a target selected, complete ancestry and known compatibility are required.</p></div>':`<div class="table-wrap"><table><thead><tr><th>Parents${p.includeSupports?' & deck':''}</th><th>Affinity</th><th>Expected outcomes</th><th>Balanced / 100</th><th>Ranking score</th><th>Average chance</th><th>All in one run ≈</th><th>Average runs ≈</th>${p.wanted.map(id=>`<th>${esc(sparkName(id))}</th>`).join('')}</tr></thead><tbody>${results.top.map((r,i)=>{const a=results.veterans?.find(v=>v.id===r.a)??state.collections.veterans.find(v=>v.id===r.a),b=results.veterans?.find(v=>v.id===r.b)??state.collections.veterans.find(v=>v.id===r.b);return `<tr><td class="name">${esc(charName(a.cardId))} + ${esc(charName(b.cardId))}<span class="row-sub">Veteran #${esc(a.id)} + #${esc(b.id)}</span>${remoteBorrowLabel(a)}${remoteBorrowLabel(b)}<div class="result-actions"><button class="small" data-apply-pair="${i}" ${results.stale?'disabled':''}>Use pair</button><button class="small" data-explain-pair="${i}">Why this match?</button><button class="small" data-compare-pair="${i}" aria-pressed="${compared.includes(i)}">${compared.includes(i)?'Selected':'Compare'}</button></div>${r.deck?`<details><summary>View deck · ${esc(scenarioNames[r.training?.scenario]??'')}</summary>${deckMarkup(r.deck,r.acquisition,r.training,r.combinedScore,p.wanted)}</details>`:''}</td><td>${r.baseline?'Not used':r.total}</td><td>${r.farming?.expectedYield?.toFixed(2)??'—'}</td><td>${r.farming?.balanced==null?'—':(r.farming.balanced*100).toFixed(2)}</td><td>${r.combinedScore?.toFixed(2)??'Minimum → total'}</td><td class="percent">${r.average===null?'—':pct(r.average)}</td><td>${jointPct(r.allChance)}</td><td>${runs(r.expectedRuns)}</td>${r.chances.map(c=>`<td class="percent">${pct(c)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`}</div>`;restore();}
function renderCollection(){return heading('YOUR ROSTER','A collection with context.','Browse what you own, filter veterans, and bring candidates into your lineage.',`<button data-action="export-backup">Export backup</button>`)+`<div class="tabs">${['veterans','trainees','supports'].map(k=>`<button data-collection="${k}" class="${collection.kind===k?'active':''}">${{veterans:'Veterans',trainees:'Trainees',supports:'Support cards'}[k]} <span class="badge">${state.collections[k].length}</span></button>`).join('')}</div><div class="panel">${collection.kind==='veterans'?searchUI.markup('collection'):`<div class="toolbar"><label class="grow">Search<input id="collection-query" placeholder="Name, outfit, ID or memo…" value="${esc(collection.query)}"></label><label>Sort<select id="collection-sort">${metaOptions(['rating','name','newest','sparks','stars','level'],x=>x,x=>({rating:'Rating / rarity',name:'Name A–Z',newest:'Newest / ID',sparks:'Spark count',stars:'Spark stars',level:'Level / awakening'}[x]),collection.sort)}</select></label>${collection.kind!=='supports'?`<label>Aptitude<select id="collection-aptitude"><option value="">Any</option>${metaOptions(aptitudes,a=>a[0],a=>a[0],collection.aptitude)}</select></label><label>Minimum grade<select id="collection-grade">${metaOptions([1,2,3,4,5,6,7,8],x=>x,x=>grades[x],collection.grade)}</select></label>`:`<label>Card type<select id="collection-type"><option value="">Any</option>${metaOptions([...new Set(D.supports.map(s=>s.supportCardTypeName))],x=>x,x=>x,collection.type)}</select></label>`}</div>`} <div id="collection-rows"></div></div>`;}
function filteredRows(){if(collection.kind==='veterans'){const r=veteranSearch.run(state.collections.veterans,state.searches.collection);const status=$('[data-search-panel=collection] .search-validation');if(status){status.textContent=r.error?'Search error: '+r.error:`${r.rows.length} veterans match`;status.classList.toggle('error',!!r.error);}return r.rows;}let rows=[...state.collections[collection.kind]];const q=collection.query.toLowerCase().trim();rows=rows.filter(r=>{
 const s=collection.kind==='supports'?support(r.cardId):null,c=char(r.cardId);const name=s?`${s.charaName} ${s.supportCardTitle}`:title(r.cardId);
 if(q&&!`${name} ${r.id} ${r.cardId} ${r.memo??''}`.toLowerCase().includes(q))return false;
 if(collection.kind==='supports'&&collection.type&&s?.supportCardTypeName!==collection.type)return false;
 if(collection.kind!=='supports'&&collection.aptitude){const a=aptitudes.find(a=>a[0]===collection.aptitude),g=collection.kind==='veterans'?r.aptitudes[a[0]]:grades.indexOf(c?.[a[2]]);if(g<collection.grade)return false;}
 if(collection.kind==='veterans'&&collection.spark){const fs=collection.scope==='lineage'?[...r.sparks,...r.parents.flatMap(p=>p.sparks)]:r.sparks;if(!fs.some(f=>f.id===Number(collection.spark)&&f.stars>=collection.minStars))return false;}return true;});
 const sparkList=r=>collection.scope==='lineage'?[...(r.sparks??[]),...(r.parents??[]).flatMap(p=>p.sparks)]:r.sparks??[];
 rows.sort((a,b)=>{switch(collection.sort){case'name':return (collection.kind==='supports'?support(a.cardId)?.charaName??'':charName(a.cardId)).localeCompare(collection.kind==='supports'?support(b.cardId)?.charaName??'':charName(b.cardId));case'newest':return String(b.date??b.id).localeCompare(String(a.date??a.id),undefined,{numeric:true});case'sparks':return sparkList(b).length-sparkList(a).length;case'stars':return sparkList(b).reduce((s,f)=>s+f.stars,0)-sparkList(a).reduce((s,f)=>s+f.stars,0);case'level':return (b.level??b.talent??0)-(a.level??a.talent??0);default:return (b.rating??b.rarity??support(b.cardId)?.rarity??0)-(a.rating??a.rarity??support(a.cardId)?.rarity??0);}});return rows;
}
function renderRows(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/30));collection.page=Math.min(collection.page,pages-1);$('#collection-rows').innerHTML=rows.length?`<p class="tiny">${number(rows.length)} matching ${collection.kind}</p><div class="table-wrap"><table><thead><tr><th>${collection.kind==='supports'?'Support card':'Character'}</th><th>${collection.kind==='veterans'?'Rating / stats':collection.kind==='trainees'?'Rarity / awakening':'Level / limit breaks'}</th><th>${collection.kind==='veterans'?'Sparks':collection.kind==='supports'?'Type':'Aptitudes'}</th><th></th></tr></thead><tbody>${rows.slice(collection.page*30,collection.page*30+30).map(r=>{
 const s=support(r.cardId),c=char(r.cardId),name=collection.kind==='supports'?(s?.charaName??`Support ${r.cardId}`):charName(r.cardId),sub=collection.kind==='supports'?(s?.supportCardTitle??'Unknown card ID'):outfit(r.cardId);
 return `<tr><td class="name"><div class="roster-name">${collection.kind==='supports'?ref.supportArt(r.cardId):ref.portrait(r.cardId)}<div>${esc(name)}<span class="row-sub">${esc(sub)} · #${esc(r.id)}</span></div></div></td><td>${collection.kind==='veterans'?`${number(r.rating)}<span class="row-sub">${stats.map(k=>r.stats[k]).join(' / ')}</span>`:collection.kind==='trainees'?`${r.rarity}★ · Awakening ${r.talent}`:`Lv ${r.level??'?'} · ${r.limitBreak}/4 LB`}</td><td>${collection.kind==='veterans'?sparks(r.sparks,4):collection.kind==='supports'?esc(s?.supportCardTypeName??'Unknown'):`<span class="row-sub">${aptitudes.filter(a=>['A','S'].includes(c?.[a[2]])).map(a=>a[0]).join(' · ')||'No A aptitude data'}</span>`}</td><td><button class="small" data-detail="${esc(r.id)}">Inspect</button></td></tr>`}).join('')}</tbody></table></div><div class="pagination"><button class="small" data-page="-1" ${collection.page===0?'disabled':''}>← Previous</button><span>${collection.page+1} / ${pages}</span><button class="small" data-page="1" ${collection.page>=pages-1?'disabled':''}>Next →</button></div>`:`<div class="empty"><div class="empty-icon">▦</div><h2>${state.collections[collection.kind].length?'No matching records':'Your collection starts here'}</h2><p>${state.collections[collection.kind].length?'Try a different filter.':'Import your umadump JSON to browse names, aptitudes, skills and sparks.'}</p><button data-action="import">Import collection</button></div>`;}
function skillMarkup(s){return ref.card(s);}
function boughtMarkup(){const p=state.plan;return `<h3 class="source-heading">Skills bought on target</h3><p class="tiny" data-help-note="skills bought on target">${p.includeSupports?'Deck mode uses the best available source by default. Selecting a version caps the learned tier; it does not invent a missing gold source.':'Assumed learned from the career unless marked Inspiration only.'} Gold / ◎ choices change the creation base; inspiration-only skills must first be inherited. These assumptions affect Spark % mode.</p>${p.searchMode!=='sparkgen'&&!p.includeSupports?'<div class="notice">Learning choices affect Spark % only. <button class="small" data-action="use-spark-mode">Switch to Spark %</button></div>':''}${p.wanted.filter(id=>factor(id)?.type===3).map(id=>{const b=p.bought?.[id]??{},ids=D['skill-links'].factorSkills[id]??[],variants=ids.map(skill).filter(Boolean);const tiers=[...(p.includeSupports?[['auto','Automatic · best available source']]:[]),['white',sparkName(id)]];for(const v of variants){const tier=skillTier(v);if(!tiers.some(t=>t[0]===tier))tiers.push([tier,v.skillName]);}return `<div class="bought-skill"><b>${esc(sparkName(id))}</b><label>Expected learned version<select data-bought-tier="${id}" ${b.inspirationOnly?'disabled':''}>${metaOptions(tiers,t=>t[0],t=>t[1],p.includeSupports&&!b.manualTier?'auto':b.tier??'white')}</select></label><label class="check"><input type="checkbox" data-inspiration="${id}" ${b.inspirationOnly?'checked':''}> Inspiration only</label>${D['skill-links'].factorAliases[id]?'<small>Normal / + interchangeable; each ancestor counts once.</small>':''}</div>`;}).join('')||'<p class="tiny">Add desired skill sparks to set learning assumptions.</p>'}`;}
function renderSkills(){return heading('BUNDLED GAME REFERENCE','Read the fine print.','Skill effects, activation conditions, variants, and acquisition sources.')+`<div class="panel"><div class="toolbar"><label class="grow">Search skills and conditions<input id="skill-query" placeholder="Name, ID, phase_random, effect…" value="${esc(skillQuery)}"></label><label>Category<select data-skill-filter="category"><option value="">Any category</option>${metaOptions([...new Set(D.skills.map(s=>s.skillCategory))].sort(),x=>x,x=>x,skillFilters.category)}</select></label><label>Rarity<select data-skill-filter="rarity"><option value="">Any rarity</option>${metaOptions([['normal','Normal'],['gold','Gold'],['unique','Unique']],x=>x[0],x=>x[1],skillFilters.rarity)}</select></label></div><div class="toolbar"><label>Condition / race restriction<select data-skill-filter="condition"><option value="">Any condition</option>${metaOptions(['Early race','Mid race','Late race','Final spurt','Random location','Corner','Straight','Front runner','Pace chaser','Late surger','End closer','Sprint','Mile','Medium','Long'],x=>x,x=>x,skillFilters.condition)}</select></label><label>Activation check<select data-skill-filter="wit"><option value="">Any</option>${metaOptions(['Wit check','No wit check'],x=>x,x=>x,skillFilters.wit)}</select></label><label class="check"><input type="checkbox" data-skill-filter="owned" ${skillFilters.owned?'checked':''}> Has an owned character / support source</label><button data-action="reset-skill-filters">Reset filters</button></div></div><div id="skill-rows"></div>`;}
function renderSkillRows(){const q=skillQuery.toLowerCase().trim().split(/\s+/).filter(Boolean),ownedChars=new Set(state.collections.trainees.map(x=>x.cardId)),ownedSupports=new Set(state.collections.supports.map(x=>x.cardId));const rows=D.skills.filter(s=>{const tags=ref.tags(s),text=[s.skillName,s.skillId,s.activationCondition,s.activationCondition2,s.precondition,s.precondition2,s.effectSummary,s.effectSummary2,s.skillDesc,...tags].join(' ').toLowerCase(),links=D['skill-links'].skills[s.skillId];return q.every(t=>text.includes(t))&&(!skillFilters.category||s.skillCategory===skillFilters.category)&&(!skillFilters.rarity||(skillFilters.rarity==='gold'?s.rarity===2:skillFilters.rarity==='unique'?s.skillCategory==='Unique':s.rarity===1&&s.skillCategory!=='Unique'))&&(!skillFilters.condition||tags.includes(skillFilters.condition))&&(!skillFilters.wit||tags.includes(skillFilters.wit))&&(!skillFilters.owned||['characters','characterEvents','supportHints','supportEvents'].some(k=>(links?.[k]??[]).some(x=>(k.startsWith('support')?ownedSupports:ownedChars).has(x.id))));});const pages=Math.max(1,Math.ceil(rows.length/20));skillPage=Math.min(skillPage,pages-1);$('#skill-rows').innerHTML=`<p class="tiny">${rows.length} skills · snapshot ${D.metadata.retrieved} · condition tags summarize exact expression matches</p><div class="skill-grid">${rows.slice(skillPage*20,skillPage*20+20).map(skillMarkup).join('')||'<div class="empty">No matching skills.</div>'}</div><div class="pagination"><button data-skill-page="-1" ${skillPage===0?'disabled':''}>Previous</button><span>${skillPage+1} / ${pages}</span><button data-skill-page="1" ${skillPage>=pages-1?'disabled':''}>Next</button></div>`;}
function renderData(){return heading('YOUR DATA, YOUR DEVICE','Bring your collection.','Import files directly into this browser. No account, server upload or game MDB required.')+`<div class="split"><section><div class="import-card" id="drop-zone" role="button" tabindex="0" aria-label="Import JSON files"><div class="empty-icon">⇅</div><h2>Drop your JSON files here</h2><p>or click to choose all three at once</p><span class="badge">UMADUMP · JSON ONLY</span></div><div class="panel" style="margin-top:20px"><h2>Imported collections</h2>${['trainees','supports','veterans'].map(k=>`<div class="file-row"><div><b>${{trainees:'card_data.json',supports:'support_card_data.json',veterans:'trained_chara_data.json'}[k]}</b><small>${state.collections[k].length} records${state.imports[k]?` · ${esc(state.imports[k].filename)} · ${new Date(state.imports[k].importedAt).toLocaleDateString()}`:''}</small></div><button class="small danger" data-remove-collection="${k}" ${!state.collections[k].length?'disabled':''}>Remove</button></div>`).join('')}<p class="tiny">File contents identify the collection, so trained_char_data.json works too. Reimporting replaces that collection; saved plan snapshots remain. Account IDs are not retained.</p></div><div class="panel"><h2>Backup & restore</h2><p>Back up the roster, current plan and saved plans before clearing browser data or changing devices. A backup contains your collection and personal memos.</p><div class="actions"><button data-action="export-backup">Export backup</button><button data-action="restore">Restore backup / plan</button></div></div></section><section><div class="panel"><div class="eyebrow">GAME DATA SNAPSHOT</div><h2>${D.metadata.retrieved} · Global</h2><div class="file-row"><span>Character outfits</span><b>${D.characters.length}</b></div><div class="file-row"><span>Support cards</span><b>${D.supports.length}</b></div><div class="file-row"><span>Skills with technical details</span><b>${D.skills.length}</b></div><div class="file-row"><span>Compatibility characters</span><b>${D.affinity.chars.length}</b></div><p>Names, aptitudes and skill expressions come from uma.guide’s public data bundle. Spark definitions, compatibility tables and G1 groups come from uma.moe’s public resources.</p><p>Unknown IDs remain visible. Target-specific parent search excludes characters without compatibility data; affinity-free search can include them. New game releases require refreshing the bundled snapshot; it does not silently update while you plan.</p><p><a href="https://uma.guide/roster-viewer/" target="_blank" rel="noreferrer">uma.guide ↗</a> · <a href="https://uma.moe/lineage-planner" target="_blank" rel="noreferrer">uma.moe ↗</a> · <a href="https://github.com/Werseter/umadump" target="_blank" rel="noreferrer">umadump ↗</a></p></div><div class="panel"><h2>How this app handles imports</h2><p>Records are validated before any collection is replaced. Veteran ancestry uses position IDs 10 and 20. Spark stars are decoded from factor IDs, including exports where level is zero.</p><p>Storage is local to this site and browser. Artwork loads from uma.guide, which receives image requests but not your JSON files. No telemetry or third-party scripts run here. Clearing site data removes your saved workspace.</p><div class="notice">This is an independent implementation of the requested tools, not an embedded copy of either website.</div></div></section></div>`;}
function openModal(html,{nested=false}={}){const modal=$('#modal');if(modal.open&&nested)modalHistory.push({html:$('#modal-body').innerHTML,scroll:modal.scrollTop});else{modalHistory=[];if(!modal.open)modalOpener=document.activeElement;}$('#modal-body').innerHTML=html;if(modalHistory.length)$('#modal-body .modal-top').insertAdjacentHTML('afterbegin','<button class="small" data-action="modal-back">← Back</button>');if(!modal.open)modal.showModal();modal.scrollTop=0;$('#modal-body button')?.focus({preventScroll:true});}
function modalHeader(text){return `<div class="modal-top"><h2>${esc(text)}</h2><button data-action="close-modal" aria-label="Close">✕</button></div>`;}
function showPicker(index,kind){pickerLimit=80;pickerIndex=index;pickerKind=kind??(index===0?'characters':'veterans');if(pickerKind==='characters'&&['rating','stars'].includes(pickerFilters.sort)||pickerKind==='veterans'&&pickerFilters.sort.startsWith('growth:'))pickerFilters.sort='affinity';const n=state.plan.nodes[index];openModal(modalHeader(labels[index])+`<div class="tabs"><button data-picker-kind="veterans" class="${pickerKind==='veterans'?'active':''}">Imported veterans</button><button data-picker-kind="characters" class="${pickerKind==='characters'?'active':''}">Plan a character</button></div>${pickerControls()}<p id="picker-count" class="tiny" role="status"></p><div id="picker-list" class="picker-list"></div><button class="small" data-action="picker-more" id="picker-more" hidden>Show 80 more</button>${n.cardId?`<hr><h3>Selected: ${esc(title(n.cardId))}</h3><p class="tiny">Manual edits change this plan only. They do not change your imported veteran.</p>${sparks(n.sparks)}<div class="toolbar"><label class="grow">Spark<select id="node-factor">${metaOptions([...engine.factors.values()],f=>f.id,f=>f.text)}</select></label><label>Stars<select id="node-stars"><option>1</option><option>2</option><option selected>3</option></select></label><button data-action="node-add-spark">Add / update</button></div><div class="chips">${n.sparks.map(f=>`<button class="chip" data-node-remove-spark="${f.id}">${esc(sparkName(f.id))} ×</button>`).join('')}</div><details><summary>G1 race wins (${n.wins.length} recorded saddle IDs)</summary><p class="tiny">Selecting a G1 adds its shared-win group to this planned character.</p><div class="toolbar"><label class="grow">Race<select id="node-race">${metaOptions(uniqueRaces(),r=>r.id,r=>r.name)}</select></label><button data-action="node-add-race">Add win</button></div><div class="chips">${n.wins.map(id=>`<button class="chip" data-node-remove-race="${id}">${esc(D.races[id]?.name??`Saddle #${id}`)} ×</button>`).join('')}</div></details>`:''}`);renderPickerList();}
function uniqueRaces(){const m=new Map();Object.entries(D.races).forEach(([id,r])=>{if(!m.has(r.group))m.set(r.group,{id,...r});});return [...m.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function candidateAffinity(v){let nodes;if(pickerKind==='veterans')nodes=placeVeteran(state.plan,pickerIndex,v).nodes;else {nodes=structuredClone(state.plan.nodes);nodes[pickerIndex]={...emptyNode(),cardId:v.cardId};}const issues=validateTree(nodes);if(issues.length)return {text:'Invalid relationship',value:-1,invalid:true};
 // The additional eight slots belong to a future parent's local seven-slot tree.
 let label='Lineage';if(pickerIndex>=7){const center=Math.floor((Math.floor((pickerIndex-1)/2)-1)/2);const p1=center*2+1,p2=p1+1;nodes=[center,p1,p2,p1*2+1,p1*2+2,p2*2+1,p2*2+2].map(i=>nodes[i]);label='Branch';}
 if(!nodes[0].cardId)return {text:'Choose target for affinity',value:0};const ev=engine.evaluate(nodes,state.plan.parentRaceBonus);if(nodes.some(n=>n.cardId&&!engine.index.has(baseId(n.cardId))))return {text:'Affinity unavailable',value:-1};return {text:`${label} affinity ${ev.total}${ev.complete?'':' · partial'}`,value:ev.total};}
function pickerControls(){const f=pickerFilters;const sorts=[['affinity','Affinity · highest'],['name','Name · A–Z'],['id','Card ID · newest'],...(pickerKind==='veterans'?[['rating','Rating · highest'],['stars','Spark stars · most']]:['Speed','Stamina','Power','Guts','Wisdom'].map(k=>['growth:'+k,(k==='Wisdom'?'Wit':k)+' growth · highest']))];return `<label>Search by character, outfit or ID<input id="picker-query" placeholder="Search…" autocomplete="off" value="${esc(f.query)}"></label><div class="picker-filters"><label>Sort by<select data-picker-filter="sort">${metaOptions(sorts,x=>x[0],x=>x[1],f.sort)}</select></label><label>Aptitude<select data-picker-filter="aptitude"><option value="">Any aptitude</option>${metaOptions(aptitudes,a=>a[0],a=>a[0],f.aptitude)}</select></label><label>Minimum grade<select data-picker-filter="grade">${metaOptions([8,7,6,5,4,3,2,1],x=>x,x=>grades[x],f.grade)}</select></label></div><div class="toolbar picker-toggles">${pickerKind==='characters'?`<label class="check"><input type="checkbox" data-picker-filter="owned" ${f.owned?'checked':''}> Owned trainees only</label>`:''}<label class="check"><input type="checkbox" data-picker-filter="valid" ${f.valid?'checked':''}> Hide invalid relationships</label><button class="small" data-action="picker-reset">Reset filters</button></div>${pickerKind==='veterans'?'<p class="tiny">Candidate filters from the planner also apply. Aptitudes use each veteran’s trained grades.</p>':''}`;}
function renderPickerList(){const source=pickerKind==='veterans'?veteranSearch.run(state.collections.veterans,state.searches.planner):{rows:D.characters};const rows=filterPickerRows(source.rows,{...pickerFilters,kind:pickerKind},D.characters,state.collections.trainees,candidateAffinity);$('#picker-count').textContent=source.error?`Candidate filter error: ${source.error}`:`${rows.length} matches · showing ${Math.min(rows.length,pickerLimit)}`;$('#picker-list').innerHTML=rows.slice(0,pickerLimit).map(({v,aff})=>{const c=char(v.cardId);let extra=pickerKind==='veterans'?`Veteran #${v.id} · Rating ${number(v.rating)}`:`${state.collections.trainees.some(t=>t.cardId===v.cardId)?'Owned':'Not imported'} · ${v.cardId}`;if(pickerFilters.sort.startsWith('growth:'))extra+=` · +${c?.['talent'+pickerFilters.sort.split(':')[1]]??0}% growth`;if(pickerFilters.aptitude){const a=aptitudes.find(a=>a[0]===pickerFilters.aptitude);extra+=` · ${a[0]} ${pickerKind==='veterans'?grades[v.aptitudes?.[a[0]]]??'?':c?.[a[2]]??'?'}`;}return `<button class="pick-row" data-pick="${pickerKind==='veterans'?esc(v.id):v.cardId}" ${aff.invalid?'disabled':''}>${ref.portrait(v.cardId)}<div class="grow"><b>${esc(charName(v.cardId))}</b><span>${esc(outfit(v.cardId))}</span><span class="row-sub">${esc(extra)}</span></div><strong class="affinity-preview">${esc(aff.text)}</strong></button>`;}).join('')||'<p>No matching characters. Change your filters or import your collection.</p>';$('#picker-more').hidden=rows.length<=pickerLimit;}

function inspect(id){detailId=id;const r=state.collections[collection.kind].find(r=>r.id===id);if(!r)return;
 if(collection.kind==='veterans')openModal(modalHeader(title(r.cardId))+`${ref.portrait(r.cardId)}<p class="tiny">Veteran #${esc(r.id)} · rating ${number(r.rating)} · ${esc(r.date)}</p><div class="stat-grid">${stats.map(k=>`<div>${{wiz:'Wit'}[k]??k}<b>${r.stats[k]}</b></div>`).join('')}</div><div class="aptitudes">${aptitudes.map(a=>`<span>${a[0]} <b>${grades[r.aptitudes[a[0]]]??'?'}</b></span>`).join('')}</div><h3>Sparks</h3>${sparks(r.sparks)}<h3 style="margin-top:20px">Recorded parents</h3>${r.parents.map(p=>`<p>${esc(title(p.cardId))}</p>${sparks(p.sparks)}`).join('')||'<p>No ancestors included in this record.</p>'}<h3 style="margin-top:20px">Learned skills</h3>${r.skills.map(s=>skill(s.id)?skillMarkup(skill(s.id)):`<p>Unknown skill #${s.id}</p>`).join('')||'<p>No skills recorded.</p>'}<p>Memo: ${esc(r.memo||'—')}</p><div class="actions"><button class="primary" data-detail-place="1">Use as parent 1</button><button class="primary" data-detail-place="2">Use as parent 2</button></div>`);
 else if(collection.kind==='trainees'){const c=char(r.cardId);openModal(modalHeader(title(r.cardId))+`${ref.portrait(r.cardId)}<p>${r.rarity}★ · Awakening ${r.talent}</p><div class="aptitudes">${aptitudes.map(a=>`<span>${a[0]} <b>${esc(c?.[a[2]]??'?')}</b></span>`).join('')}</div><h3>Growth bonuses</h3><p>${['Speed','Stamina','Power','Guts','Wisdom'].map(k=>`${k}: ${c?.['talent'+k]??'?'}%`).join(' · ')}</p><button class="primary" data-target="${r.cardId}">Plan this trainee</button>`);}
 else {const s=support(r.cardId);openModal(modalHeader(`${s?.charaName??'Unknown support'} ${s?.supportCardTitle??r.cardId}`)+`${ref.supportArt(r.cardId)}<p>${esc(s?.rarityDisplay??'?')} · ${esc(s?.supportCardTypeName??'?')} · Level ${r.level??'unknown'} · ${r.limitBreak}/4 limit breaks</p><h3>Skill hints</h3>${(s?.skillHints??[]).map(h=>{const sk=skill(h.skillId);return sk?skillMarkup(sk):`<p>${esc(h.skillName??h.name??`Skill #${h.skillId}`)}</p>`}).join('')||'<p>No hints in this snapshot.</p>'}`);}
}
async function importFiles(files){try{
 const incoming=[];for(const file of files){if(file.size>35*1024*1024)throw Error(`${file.name} exceeds 35 MB.`);incoming.push(normalizeImport(JSON.parse(await file.text()),file.name,engine.factors));}
 if(new Set(incoming.map(x=>x.kind)).size!==incoming.length)throw Error('Choose only one file for each collection in a single import.');
 const next=structuredClone(state);for(const item of incoming){next.collections[item.kind]=item.data;next.imports[item.kind]={filename:item.filename,importedAt:item.importedAt};}
 // Persist before replacing the in-memory workspace; a failure leaves the old roster intact.
 await writeState(next);state=next;searchUI?.migrate();invalidate();render();notify(`Imported ${incoming.map(x=>`${x.data.length} ${x.kind}`).join(', ')}.`);
 }catch(e){notify(`Import failed: ${e.message}`);}finally{$('#import-files').value='';}}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validatePlan(p){if(!p||!Array.isArray(p.nodes)||p.nodes.length!==15||!Array.isArray(p.wanted)||!Array.isArray(p.pins)||p.pins.length!==2||![1,2].includes(p.rolls))throw Error('Invalid plan structure.');for(const n of p.nodes){if(!Number.isSafeInteger(n.cardId)||n.cardId<0||!Array.isArray(n.sparks)||!Array.isArray(n.wins)||n.wins.some(x=>!Number.isSafeInteger(x)||x<=0)||n.sparks.some(f=>!Number.isSafeInteger(f.id)||f.id<=0||![1,2,3].includes(f.stars)))throw Error('Invalid lineage node.');}if(p.wanted.some(id=>!Number.isSafeInteger(id)||id<=0))throw Error('Invalid desired sparks.');p.bought=p.bought&&typeof p.bought==='object'&&!Array.isArray(p.bought)?p.bought:{};for(const [id,b] of Object.entries(p.bought)){if(!b||!['white','upgraded','gold'].includes(b.tier??'white')||typeof(b.inspirationOnly??false)!=='boolean')throw Error('Invalid skill learning assumptions.');}p.scenario=Object.hasOwn(scenarioNames,p.scenario)?p.scenario:'auto';p.autoScenarios=Array.isArray(p.autoScenarios)?p.autoScenarios.filter(k=>Object.hasOwn(scenarioNames,k)):['URA','Aoharu','MANT','GL'];p.trainingFocus=['balanced','speed','stamina','power','guts','wisdom'].includes(p.trainingFocus)?p.trainingFocus:'balanced';p.trainingWeight=Number.isFinite(Number(p.trainingWeight??25))?Math.max(0,Math.min(100,Number(p.trainingWeight??25))):25;p.training=p.training&&Number.isFinite(p.training.score)&&Array.isArray(p.training.comparisons)&&Array.isArray(p.training.missing)?p.training:null;p.maxOutingCards=Number.isInteger(p.maxOutingCards)?Math.max(0,Math.min(6,p.maxOutingCards)):1;p.deckMode=p.deckMode==='manual'?'manual':'auto';p.manualDeck=Array.isArray(p.manualDeck)&&p.manualDeck.length===6?p.manualDeck.map(id=>Number.isSafeInteger(id)&&id>=0?id:0):Array(6).fill(0);p.includeRemote=!!p.includeRemote;p.includeSupports=!!p.includeSupports;p.borrowSSR=p.borrowSSR!==false;p.deck=Array.isArray(p.deck)?p.deck.filter(c=>Number.isSafeInteger(c.id)).slice(0,6):[];p.farmingObjective=Object.hasOwn(objectives,p.farmingObjective)?p.farmingObjective:'legacy';p.sparkWeights=Object.fromEntries(p.wanted.map(id=>[id,priority(p,id)]));p.searchMode=p.searchMode==='sparkgen'?'sparkgen':'inherit';delete p.minChance;p.name=String(p.name??'Imported plan').slice(0,200);return p;}
async function restore(file){try{if(file.size>50*1024*1024)throw Error('Backup exceeds 50 MB.');const incoming=JSON.parse(await file.text());let next;
 if(incoming.format==='umaplan-plan'&&incoming.version===1){next=structuredClone(state);next.plan=validatePlan(incoming.plan);}
 else if(incoming.format==='umaplan-backup'&&incoming.version===1){next=incoming.workspace;if(next?.schema!==1||!next.collections||!next.imports||!Array.isArray(next.saved))throw Error('Invalid workspace.');validatePlan(next.plan);next.saved.forEach(validatePlan);next.remoteParents=validateRemotePool(next.remoteParents);if(next.farmingPresets!==undefined){if(!Array.isArray(next.farmingPresets)||next.farmingPresets.length>100)throw Error('Invalid farming preset list.');next.farmingPresets=next.farmingPresets.map(checkedFarmingPreset);}for(const k of ['trainees','supports','veterans']){if(!Array.isArray(next.collections[k])||next.collections[k].length>30000)throw Error('Invalid collections.');for(const r of next.collections[k]){if(!r||typeof r.id!=='string'||!Number.isSafeInteger(r.cardId)||r.cardId<=0)throw Error('Invalid collection record.');if(k==='veterans'){if(!Array.isArray(r.parents)||!r.stats||!r.aptitudes||!Array.isArray(r.skills))throw Error('Invalid veteran.');for(const v of [r,...r.parents]){if(!Array.isArray(v.sparks)||!Array.isArray(v.wins)||v.sparks.some(f=>!Number.isSafeInteger(f.id)||![1,2,3].includes(f.stars)))throw Error('Invalid veteran sparks.');}}}}}
 else throw Error('This is not a Umaplan backup or plan. Use Import collection for umadump files.');
 openModal(modalHeader('Restore this file?')+`<p>${incoming.format==='umaplan-backup'?'This replaces this browser’s collections, current plan, and saved plans.':'This replaces only the current plan.'} Export a backup first if you want to keep the existing workspace.</p><div class="actions"><button class="primary" id="confirm-restore">Restore</button><button data-action="close-modal">Cancel</button></div>`);
 $('#confirm-restore').onclick=async()=>{try{await writeState(next);state=next;searchUI?.migrate();invalidate();$('#modal').close();render({preserve:false});notify('Restored successfully.');}catch(e){notify(`Restore failed: ${e.message}`);}};
 }catch(e){notify(`Restore failed: ${e.message}`);}finally{$('#backup-file').value='';}}
function showSearchStatus(message,busy=false){searchMessage=message;const el=$('#search-status');if(el){el.textContent=message;if(busy)el.insertAdjacentHTML('beforeend',' <button class="small" data-action="cancel-search">Cancel</button>');}$('#results')?.setAttribute('aria-busy',String(busy));}
function manualDeckControls(){const p=state.plan,ids=p.manualDeck??Array(6).fill(0),owned=new Map(state.collections.supports.map(c=>[c.cardId,c]));return `<label>Deck selection<select id="deck-mode"><option value="auto" ${p.deckMode!=='manual'?'selected':''}>Automatic · suggest a deck</option><option value="manual" ${p.deckMode==='manual'?'selected':''}>Manual · use my six cards</option></select></label>${p.deckMode==='manual'?`<div class="manual-deck-grid">${ids.map((id,i)=>{const rows=D.supports.filter(c=>i===5||owned.has(c.supportCardId)).sort((a,b)=>a.charaName.localeCompare(b.charaName)||b.rarity-a.rarity||a.supportCardId-b.supportCardId);return `<div class="manual-slot"><label>${i===5?'Borrowed support · MLB':`Owned support ${i+1}`}<select data-manual-slot="${i}" aria-label="${i===5?'Borrowed support':`Owned support ${i+1}`}"><option value="0">Choose a card…</option>${id&&!rows.some(c=>c.supportCardId===id)?`<option value="${id}" selected>Unavailable card #${id}</option>`:''}${rows.map(c=>`<option value="${c.supportCardId}" ${id===c.supportCardId?'selected':''}>${esc(c.charaName)} ${esc(c.supportCardTitle)} · ${esc(c.rarityDisplay)} · ${esc(c.supportCardTypeName)} · #${c.supportCardId}${i<5?' · '+owned.get(c.supportCardId).limitBreak+'/4 LB':''}</option>`).join('')}</select></label>${id?ref.supportArt(id):''}</div>`;}).join('')}</div><p class="tiny">Your exact six cards are evaluated for every parent pair. Auto-search type minimums, race-bonus minimums, SSR-only and Pal limits are ignored; character and scenario restrictions still apply. The borrowed card is modeled at MLB/max level.</p><button class="small" data-action="manual-from-applied" ${p.deck?.length!==6?'disabled':''}>Copy applied deck</button>`:''}`;}
function remotePoolMarkup(){const pool=state.remoteParents??[];return `<details id="remote-pool"><summary>uma.moe remote parents · ${pool.length} saved</summary><label class="check"><input type="checkbox" id="include-remote" ${state.plan.includeRemote?'checked':''}> Include remote parents in pair search</label><p class="tiny">At most one remote parent per pair. Only the snapshots you add here are searched, alongside your filtered roster.</p><button class="small" data-action="remote-open">Find a remote parent</button>${pool.map(v=>`<div class="remote-saved"><b>${esc(charName(v.cardId))}</b><span>${esc(v.trainerName)} · Trainer ${esc(v.trainerId)}</span><span class="tiny">Fetched ${esc(v.fetchedAt?.slice(0,10)??'unknown')} · ${v.followerCount} followers</span><div class="actions"><button class="small" data-remote-place="${esc(v.id)}" data-remote-side="1">Parent 1</button><button class="small" data-remote-place="${esc(v.id)}" data-remote-side="2">Parent 2</button><button class="small" data-remote-remove="${esc(v.id)}">Remove</button></div></div>`).join('')}</details>`;}
function remoteBorrowLabel(v){return v?.remote?`<span class="row-sub remote-borrow">Borrowed · ${esc(v.trainerName)} · Trainer ID <b>${esc(v.trainerId)}</b> · snapshot ${esc(v.fetchedAt?.slice(0,10)??'')}</span>`:'';}
function openRemoteParents(){remotePage=0;remoteRows=[];openModal(modalHeader('uma.moe remote parents')+`<p>Search public borrowable parents, then load their full lineage into your remote pool. Nothing from your collection is uploaded.</p><label>uma.moe API key<input id="remote-key" type="password" autocomplete="off" placeholder="${remoteKey?'Key already loaded for this tab':'Enter API key'}"></label><p class="tiny">Key stays in memory until this tab reloads; never included in exports.</p><label>Trainer ID (optional)<input id="remote-trainer" inputmode="numeric" placeholder="Numeric trainer ID"></label><label class="check"><input id="remote-use-goals" type="checkbox" checked> Prefer current desired skill sparks</label><p class="tiny">Without a trainer ID, this looks for at least one desired skill spark. An empty skill list searches recently updated parents. Results are a shortlist, not a complete search of the database.</p><div class="actions"><button class="primary" data-action="remote-search">Search uma.moe</button><button class="small" data-action="remote-forget-key">Forget key</button></div><div id="remote-results" role="status"></div>`);}
async function searchRemote(page=0){if(remoteBusy)return;const entered=$('#remote-key')?.value.trim();if(entered)remoteKey=entered;$('#remote-key').value='';$('#remote-key').placeholder=remoteKey?'Key loaded for this tab':'Enter API key';const trainerId=$('#remote-trainer').value.trim(),wanted=$('#remote-use-goals').checked?state.plan.wanted:[];const box=$('#remote-results');remoteBusy=true;box.textContent='Searching uma.moe…';try{const url=remoteSearchURL({trainerId,wanted,factors:engine.factors,page});const data=await moeGet(url,remoteKey,{signal:AbortSignal.timeout(20000)});if(!Array.isArray(data.items))throw Error('Unrecognized uma.moe search response.');remoteRows=data.items.filter(r=>r.inheritance&&/^\d{1,20}$/.test(String(r.account_id)));remotePage=page;if(!box.isConnected)return;box.innerHTML=`<p>${esc(data.total??remoteRows.length)} results · page ${page+1}. Load each parent to get its recorded ancestor sparks and race wins.</p>${remoteRows.map((r,i)=>`<div class="remote-result">${ref.portrait(r.inheritance.main_parent_id)}<div><b>${esc(charName(r.inheritance.main_parent_id))}</b><p>${esc(r.trainer_name)} · ${esc(r.account_id)}<br>${Number(r.follower_num)||0} followers · ${esc(String(r.last_updated??'').slice(0,10))}</p></div><button class="small" data-remote-add="${i}">Load lineage</button></div>`).join('')||'<p>No remote parents matched.</p>'}<div class="actions"><button class="small" data-remote-page="${page-1}" ${page===0?'disabled':''}>Previous</button><button class="small" data-remote-page="${page+1}" ${page+1>=Number(data.total_pages??1)?'disabled':''}>Next</button></div>`;}catch(e){if(box.isConnected)box.textContent=e.name==='TimeoutError'?'uma.moe timed out. Try again.':e.message;}finally{remoteBusy=false;}}
async function addRemoteParent(index,button){const row=remoteRows[index];if(!row||remoteBusy)return;remoteBusy=true;button.disabled=true;button.textContent='Loading…';try{const data=await moeGet(`${moeOrigin}/api/v4/user/profile/${encodeURIComponent(row.account_id)}`,remoteKey,{signal:AbortSignal.timeout(20000)});const veteran=normalizeRemoteProfile(data,engine.factors);state.remoteParents=validateRemotePool(state.remoteParents);const existing=state.remoteParents.findIndex(v=>v.trainerId===veteran.trainerId);if(existing<0&&state.remoteParents.length>=100)throw Error('Remote pool is full (100 parents). Remove a snapshot first.');if(existing>=0)state.remoteParents.splice(existing,1,veteran);else state.remoteParents.push(veteran);state.plan.includeRemote=true;invalidate();render();button.textContent='Added to pool';notify('Remote parent and ancestor snapshots added. Use the pool’s Parent 1 / Parent 2 buttons or run Find parents.');}catch(e){button.disabled=false;button.textContent='Load lineage';notify(e.name==='TimeoutError'?'uma.moe timed out. Try again.':e.message);}finally{remoteBusy=false;}}

function findParents({scroll=true}={}){
 const filtered=veteranSearch.run(state.collections.veterans,state.searches.planner);
 if(state.plan.includeRemote)filtered.rows.push(...(state.remoteParents??[]));
 if(filtered.error){notify(filtered.error);return;}
 if(state.plan.pins.some((pin,i)=>pin&&!filtered.rows.some(v=>v.id===state.plan.nodes[i+1].sourceId))){notify('A pinned parent is excluded by the candidate filters. Adjust filters or unpin it.');return;}
 searchGate.cancel();const searchedPlan=structuredClone(state.plan),searchedVeterans=structuredClone(filtered.rows);
 const run=new Worker(new URL('./search-worker.js',import.meta.url),{type:'module'});worker=run;searchGate.start(run);
 showSearchStatus('Searching eligible pairs… Previous results remain visible until this search finishes.',true);
 run.onmessage=({data})=>{
  if(!searchGate.isCurrent(run))return;
  if(data.type==='progress'){showSearchStatus(`${number(data.checked)} comparisons…`,true);return;}
  searchGate.finish(run);worker=null;
  if(data.type==='error'){showSearchStatus(data.message);notify(data.message);return;}
  results={...data,plan:searchedPlan,veterans:searchedVeterans};compared=[];
  showSearchStatus(`Complete · ${number(data.matched)} matching pairs.`);renderResults();
  if(scroll&&route==='planner')$('#results')?.scrollIntoView({behavior:'smooth',block:'start'});
 };
 run.onerror=e=>{if(!searchGate.finish(run))return;worker=null;showSearchStatus('Search failed.');notify(`Search failed: ${e.message}`);};
 run.postMessage({affinity:D.affinity,factors:D.factors,races:D.races,links:D['skill-links'],plan:searchedPlan,veterans:searchedVeterans,supports:D.supports,ownedSupports:state.collections.supports,skills:D.skills,characters:D.characters});
}
const actions={
 'remote-open':openRemoteParents,'remote-search':()=>searchRemote(0),'remote-forget-key':()=>{remoteKey='';$('#remote-key').value='';$('#remote-key').placeholder='Enter API key';notify('API key forgotten.');},
 'manual-from-applied':()=>{const cards=state.plan.deck;if(cards.length!==6||cards.filter(c=>c.borrowed).length!==1)return;state.plan.manualDeck=[...cards.filter(c=>!c.borrowed),...cards.filter(c=>c.borrowed)].map(c=>c.id);invalidate();render();},
 'use-spark-mode':()=>{state.plan.searchMode='sparkgen';invalidate();render();},
 'modal-back':()=>{const previous=modalHistory.pop();if(previous){$('#modal-body').innerHTML=previous.html;$('#modal').scrollTop=previous.scroll;$('#modal-body button')?.focus();}},
 'save-farming':saveFarmingPreset,'load-farming':loadFarmingPreset,'export-farming':()=>download('umaplan-farming-preset.json',{format:'umaplan-farming',preset:captureFarmingPreset(state.plan,state.searches.planner,$('#farming-name').value)}),'import-farming':()=>$('#farming-import').click(),'delete-farming':()=>{state.farmingPresets=(state.farmingPresets??[]).filter((_,i)=>String(i)!==$('#farming-preset').value);save();render();},'reset-farming':()=>{state.plan.farmingObjective='legacy';state.plan.sparkWeights={};invalidate();render();},

 'apply-goal':()=>{const id=$('#goal-preset').value;const next=applyGoalPreset(state.plan,id,D.factors);state.saved.push({...structuredClone(state.plan),name:state.plan.name+' (before goal preset)'});state.plan=next;invalidate();render();notify('Added goal skills and settings. Previous plan saved; existing sparks retained.');},
 'apply-deck-template':()=>{const t=deckTemplates[$('#deck-template').value];if(!t)return;state.plan.deckTemplate=$('#deck-template').value;state.plan.deckMinimums={...t.minimums};state.plan.minRaceBonus=t.raceBonus;if(t.scenario)state.plan.scenario=t.scenario;invalidate();render();notify('Deck requirements applied. Adjust the minimums for your collection.');},

 'reset-skill-filters':()=>{Object.assign(skillFilters,{category:'',rarity:'',condition:'',wit:'',owned:false});skillQuery='';skillPage=0;render();},
 'picker-more':()=>{pickerLimit+=80;renderPickerList();},
 'picker-reset':()=>{Object.assign(pickerFilters,{query:'',owned:false,valid:false,aptitude:'',grade:7,sort:'affinity'});showPicker(pickerIndex,pickerKind);},
 import:()=>$('#import-files').click(),restore:()=>$('#backup-file').click(),'close-modal':()=>$('#modal').close(),
 'new-plan':()=>{state.saved.push({...structuredClone(state.plan),name:`${state.plan.name} (previous)`});state.plan=emptyPlan();invalidate();render({preserve:false});notify('Started a new plan; the previous plan was saved.');},
 'export-plan':()=>download('umaplan-lineage.json',{format:'umaplan-plan',version:1,plan:state.plan}),
 'export-backup':()=>download('umaplan-backup.json',{format:'umaplan-backup',version:1,workspace:state}),
 'save-plan':()=>{state.plan.name=($('#plan-name').value.trim()||'Untitled lineage').slice(0,200);state.saved.push(structuredClone(state.plan));save();render();notify('Saved a plan snapshot.');},
 'add-wanted':()=>{const text=$('#wanted-search').value.trim(),match=text.match(/\(#(\d+)\)$/),id=match?Number(match[1]):[...engine.factors].find(([id,f])=>f.text.toLowerCase()===text.toLowerCase()||String(id)===text)?.[0];if(!id||!factor(id)){notify('Choose a spark from the suggestions.');return;}if(!state.plan.wanted.includes(id))state.plan.wanted.push(id);$('#wanted-search').value='';invalidate();render();},
 'find-parents':findParents,'cancel-search':()=>{searchGate.cancel();worker=null;showSearchStatus('Search cancelled. Previous results retained.');},
 'node-add-spark':()=>{const id=Number($('#node-factor').value),stars=Number($('#node-stars').value),n=state.plan.nodes[pickerIndex];n.sparks=n.sparks.filter(f=>f.id!==id);n.sparks.push({id,stars});n.sourceId=null;invalidate();render();showPicker(pickerIndex,pickerKind);},
 'node-add-race':()=>{const id=Number($('#node-race').value),n=state.plan.nodes[pickerIndex];if(!n.wins.includes(id))n.wins.push(id);n.winsKnown=true;n.sourceId=null;invalidate();render();showPicker(pickerIndex,pickerKind);}
};
document.addEventListener('click',e=>{if(searchUI?.handle(e))return;const el=e.target.closest('button,[data-action],#drop-zone');if(!el)return;try{
 if(el.dataset.explainPair!==undefined)return explainMatch(Number(el.dataset.explainPair));
 if(el.dataset.comparePair!==undefined){const i=Number(el.dataset.comparePair);compared=compared.includes(i)?compared.filter(x=>x!==i):[...compared.slice(-1),i];renderResults();if(compared.length===2)compareMatches();return;}
 if(el.id==='header-import'||el.id==='drop-zone')return actions.import();
 if(el.dataset.action)return actions[el.dataset.action]?.();
 if(el.dataset.skillSources)return openModal(modalHeader(`Sources · ${skill(el.dataset.skillSources)?.skillName}`)+ref.sources(Number(el.dataset.skillSources)),{nested:true});
 if(el.dataset.skillVariants)return openModal(modalHeader(`Variants · ${skill(el.dataset.skillVariants)?.skillName}`)+ref.variants(Number(el.dataset.skillVariants)),{nested:true});
 if(el.dataset.farmSkill){const sk=skill(el.dataset.farmSkill),id=factorForSkill(D['skill-links'],sk.skillId,state.plan.wanted);if(!id)return notify('No farmable white spark is linked to this skill.');if(!state.plan.wanted.includes(id))state.plan.wanted.push(id);updateLearning(state.plan,id,'tier',skillTier(sk));updateLearning(state.plan,id,'inspirationOnly',false);state.plan.searchMode='sparkgen';invalidate();$('#modal').close();location.hash='planner';if(route==='planner')render();notify('Added '+sparkName(id)+' with '+sk.skillName+' as the learned version.');return;}
 if(el.dataset.edit!==undefined)return showPicker(Number(el.dataset.edit));
 if(el.dataset.clearNode!==undefined){state.plan.nodes[Number(el.dataset.clearNode)]=emptyNode();invalidate();return render();}
 if(el.dataset.pickerKind){return showPicker(pickerIndex,el.dataset.pickerKind);}
 if(el.dataset.remoteAdd!==undefined){addRemoteParent(Number(el.dataset.remoteAdd),el);return;}
 if(el.dataset.remotePage!==undefined){searchRemote(Number(el.dataset.remotePage));return;}
 if(el.dataset.remoteRemove){state.remoteParents=(state.remoteParents??[]).filter(v=>v.id!==el.dataset.remoteRemove);invalidate();render();return;}
 if(el.dataset.remotePlace){const v=state.remoteParents.find(v=>v.id===el.dataset.remotePlace),slot=Number(el.dataset.remoteSide);if(state.plan.nodes[slot===1?2:1].remote){notify('Only one borrowed parent can be used in a career.');return;}const next=placeVeteran(state.plan,slot,v);const issues=validateTree(next.nodes);if(issues.length){notify(issues[0]);return;}next.includeRemote=true;next.pins[slot-1]=true;state.plan=next;invalidate();render();return;}
 if(el.dataset.pick){if(pickerKind==='veterans'){const v=state.collections.veterans.find(v=>v.id===el.dataset.pick);const next=placeVeteran(state.plan,pickerIndex,v);const issues=validateTree(next.nodes);if(issues.length){notify(issues[0]);return;}state.plan=next;}else{const next=structuredClone(state.plan);next.nodes[pickerIndex]={...emptyNode(),cardId:Number(el.dataset.pick)};const issues=validateTree(next.nodes);if(issues.length){notify(issues[0]);return;}state.plan=next;}invalidate();render();showPicker(pickerIndex,pickerKind);return;}
 if(el.dataset.nodeRemoveSpark){const n=state.plan.nodes[pickerIndex];n.sparks=n.sparks.filter(f=>f.id!==Number(el.dataset.nodeRemoveSpark));n.sourceId=null;invalidate();render();return showPicker(pickerIndex,pickerKind);}
 if(el.dataset.nodeRemoveRace){const n=state.plan.nodes[pickerIndex];n.wins=n.wins.filter(id=>id!==Number(el.dataset.nodeRemoveRace));n.sourceId=null;invalidate();render();return showPicker(pickerIndex,pickerKind);}
 if(el.dataset.removeWanted){state.plan.wanted=state.plan.wanted.filter(id=>id!==Number(el.dataset.removeWanted));updateMatchSort(state.plan,'sort','recommended');invalidate();return render();}
 if(el.dataset.loadPlan!==undefined){state.plan=validatePlan(structuredClone(state.saved[Number(el.dataset.loadPlan)]));invalidate();return render({preserve:false});}
 if(el.dataset.deletePlan!==undefined){state.saved.splice(Number(el.dataset.deletePlan),1);save();return render();}
 if(el.dataset.applyPair!==undefined){if(results.stale){notify('Run the search again before applying an outdated result.');return;}const result=results.top[Number(el.dataset.applyPair)];let next=structuredClone(state.plan);next.deck=result.deck??[];next.training=result.training??null;for(const [slot,id] of [[1,result.a],[2,result.b]])next=placeVeteran(next,slot,results.veterans.find(v=>v.id===id));state.plan=next;invalidate();render();notify('Applied parent pair and their recorded ancestors.');return;}
 if(el.dataset.collection){collection.kind=el.dataset.collection;collection.page=0;collection.query='';return render();}
 if(el.dataset.page){collection.page+=Number(el.dataset.page);return renderRows();}
 if(el.dataset.skillPage){skillPage+=Number(el.dataset.skillPage);renderSkillRows();window.scrollTo({top:0});return;}
 if(el.dataset.detail)return inspect(el.dataset.detail);
 if(el.dataset.detailPlace){state.plan=placeVeteran(state.plan,Number(el.dataset.detailPlace),state.collections.veterans.find(v=>v.id===detailId));invalidate();$('#modal').close();location.hash='planner';render();return;}
 if(el.dataset.target){state.plan.nodes[0]={...emptyNode(),cardId:Number(el.dataset.target)};invalidate();$('#modal').close();location.hash='planner';if(route==='planner')render();return;}
 if(el.dataset.removeCollection){const k=el.dataset.removeCollection;openModal(modalHeader(`Remove ${k}?`)+`<p>This removes the imported ${k} from this browser. Saved lineage snapshots remain.</p><div class="actions"><button class="danger" id="confirm-remove">Remove collection</button><button data-action="close-modal">Cancel</button></div>`);$('#confirm-remove').onclick=()=>{state.collections[k]=[];delete state.imports[k];invalidate();$('#modal').close();render();};return;}
 }catch(err){notify(err.message);}});
document.addEventListener('input',e=>{if(searchUI?.handle(e))return;const el=e.target;if(el.id==='picker-query'){pickerFilters.query=el.value;pickerLimit=80;renderPickerList();}if(el.id==='collection-query'){collection.query=el.value;collection.page=0;renderRows();}if(el.id==='skill-query'){skillQuery=el.value;skillPage=0;renderSkillRows();}});
document.addEventListener('change',e=>{if(searchUI?.handle(e))return;const el=e.target;
 if(el.id==='deck-mode'){state.plan.deckMode=el.value;invalidate();render();return;}
 if(el.dataset.manualSlot!==undefined){state.plan.manualDeck??=Array(6).fill(0);state.plan.manualDeck[Number(el.dataset.manualSlot)]=Number(el.value);invalidate();render();return;}
 if(el.id==='include-remote'){state.plan.includeRemote=el.checked;invalidate();render();return;}
 if(el.id==='farming-objective'){state.plan.farmingObjective=el.value;state.plan.matchSort='recommended';invalidate();render();return;}
 if(el.dataset.sparkWeight||el.dataset.priorityLevel){const id=el.dataset.sparkWeight??el.dataset.priorityLevel;state.plan.sparkWeights??={};state.plan.sparkWeights[id]=Number(el.value);state.plan.sparkWeights[id]=priority(state.plan,id);invalidate();render();return;}
 if(el.id==='farming-import'&&el.files[0]){importFarmingPreset(el.files[0]);return;}
 if(el.dataset.pickerFilter){pickerFilters[el.dataset.pickerFilter]=el.type==='checkbox'?el.checked:el.value;pickerLimit=80;renderPickerList();return;}
 if(el.id==='match-sort'||el.id==='match-direction'){updateMatchSort(state.plan,el.id==='match-sort'?'sort':'direction',el.value);save();renderResults();findParents({scroll:false});return;}
 if(el.dataset.pin!==undefined){state.plan.pins[Number(el.dataset.pin)]=el.checked;invalidate();}
 if(el.id==='parent-race'){state.plan.parentRaceBonus=el.checked;invalidate();render();}
 if(el.id==='rolls'){state.plan.rolls=Number(el.value);invalidate();render();}
 if(el.dataset.autoScenario){const a=new Set(state.plan.autoScenarios??['URA','Aoharu','MANT','GL']);el.checked?a.add(el.dataset.autoScenario):a.delete(el.dataset.autoScenario);state.plan.autoScenarios=[...a];invalidate();render();}
 if(el.dataset.deckMinimum){state.plan.deckTemplate='custom';state.plan.deckMinimums??={};state.plan.deckMinimums[el.dataset.deckMinimum]=Math.max(0,Math.min(6,Math.trunc(Number(el.value)||0)));invalidate();render();}
 if(el.id==='min-race-bonus'){state.plan.deckTemplate='custom';state.plan.minRaceBonus=Math.max(0,Math.min(100,Number(el.value)||0));invalidate();render();}
 if(el.id==='count-event-sources'||el.id==='scenario-hints'){state.plan[el.id==='count-event-sources'?'countEventSources':'scenarioHints']=el.checked;invalidate();render();}
 if(el.id==='course-context'){state.plan.courseId=Number(el.value)||null;save();render();}
 if(el.id==='recovery-adjustment'){state.plan.recoveryAdjustment=el.checked;invalidate();render();}
 if(el.id==='max-outing-cards'){state.plan.maxOutingCards=Number(el.value);invalidate();render();}
 if(['training-scenario','training-focus','training-weight'].includes(el.id)){state.plan[{'training-scenario':'scenario','training-focus':'trainingFocus','training-weight':'trainingWeight'}[el.id]]=el.id==='training-weight'?Number(el.value):el.value;invalidate();render();}
 if(el.id==='include-supports'||el.id==='borrow-ssr'){state.plan[el.id==='include-supports'?'includeSupports':'borrowSSR']=el.checked;invalidate();render();}
 if(el.id==='search-mode'){state.plan.searchMode=el.value;invalidate();render();}
 if(el.dataset.boughtTier||el.dataset.inspiration){const id=el.dataset.boughtTier??el.dataset.inspiration;state.plan.bought??={};updateLearning(state.plan,id,el.dataset.boughtTier?'tier':'inspirationOnly',el.dataset.boughtTier?el.value:el.checked);invalidate();render();}
 if(el.dataset.skillFilter){skillFilters[el.dataset.skillFilter]=el.type==='checkbox'?el.checked:el.value;skillPage=0;renderSkillRows();}
 const map={'collection-sort':'sort','collection-aptitude':'aptitude','collection-grade':'grade','collection-spark':'spark','collection-stars':'minStars','collection-scope':'scope','collection-type':'type'};
 if(map[el.id]){collection[map[el.id]]=['grade','minStars'].includes(map[el.id])?Number(el.value):el.value;collection.page=0;renderRows();}
 if(el.id==='import-files')importFiles([...el.files]);if(el.id==='backup-file'&&el.files[0])restore(el.files[0]);
});
document.addEventListener('error',e=>{if(e.target.matches?.('.art img')){e.target.hidden=true;e.target.parentElement.classList.add('art-missing');}},true);
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();$('#drop-zone').classList.add('drag');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#drop-zone'))$('#drop-zone').classList.remove('drag');});
document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();importFiles([...e.dataTransfer.files]);}});
document.addEventListener('keydown',e=>{if(e.target.id==='drop-zone'&&['Enter',' '].includes(e.key)){e.preventDefault();actions.import();}});
$('#modal').addEventListener('close',()=>{modalHistory=[];if(modalOpener?.isConnected)modalOpener.focus({preventScroll:true});});
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();go();});
async function boot(){try{const names=['characters','supports','skills','factors','races','affinity','metadata','skill-links','courses'];D=Object.fromEntries(await Promise.all(names.map(async n=>{const r=await fetch(`./data/${n}.json`);if(!r.ok)throw Error(`Could not load ${n}.json (${r.status}).`);return[n,await r.json()];})));engine=new Engine(D.affinity,D.factors,D.races,D['skill-links']);ref=createReference(D,esc);try{state=await readState()??initial();validatePlan(state.plan);state.remoteParents=validateRemotePool(state.remoteParents);}catch(e){state=initial();notify('Could not restore local data. Import a backup if you have one.');}veteranSearch=createVeteranSearch(D,engine);searchUI=createSearchUI({service:veteranSearch,esc,getState:()=>state,notify,changed:(refresh=true,key)=>{plannerFiltersOpen=$('#planner-filters')?.open??plannerFiltersOpen;collection.page=0;if(key==='planner')invalidate();else save();if(refresh)render();else{const key=route==='collection'?'collection':'planner',r=veteranSearch.run([],state.searches[key]),status=$(`[data-search-panel=${key}] .search-validation`);if(status){status.textContent=r.error?'Search error: '+r.error:'Filters ready';status.classList.toggle('error',!!r.error);}if(route==='collection')renderRows();if($('#results'))renderResults();}}});searchUI.migrate();$('#snapshot').textContent=`Global snapshot · ${D.metadata.retrieved}`;go();}catch(e){$('#main').innerHTML=`<div class="empty"><h1>Unable to load Umaplan</h1><p>${esc(e.message)}</p><p>Open the app through GitHub Pages or a local HTTP server, rather than opening index.html directly.</p><button onclick="location.reload()">Retry</button></div>`;}}
installHelp();
boot();
